window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q13"]=window.__LIBQ["the-gioi-hoan-my"]["q13"]||{};window.__LIBQ["the-gioi-hoan-my"]["q13"]["cotTruyen"]=[{"chuong":1201,"tieuDe":"Phản Ngũ Hành","tomTat":"Các lão quái vật Tiên viện xuất hiện trên Ngũ hành đại lục, đánh giá cao một số đệ tử và ngầm bộc lộ ý định tuyển mộ nhân tài của Thiên Thần thư viện. Nhị trưởng lão yêu cầu Thạch Hạo trả xanh thẳm giáp trụ, nhưng hắn khẳng định đây là chiến lợi phẩm và không chịu nhượng bộ dù được cảnh báo về Tiểu Thiên Vương. Ngô Thái tiết lộ Tiểu Thiên Vương đã dung hợp tiên chủng thần bí và đạt cấp độ Giáo chủ từ hai năm trước, song lão quái vật Tiên viện vẫn cho phép Thạch Hạo tạm giữ giáp trụ để nghiên cứu. Sau khi đoàn Tiên viện rời đi, đệ tử Thiên Thần thư viện tiếp tục tìm Ngũ hành hạt giống nhưng chỉ thu được hai viên hỏa đạo chủng tử. Các trưởng lão sau đó lấy chuẩn Thế Giới thụ làm trung tâm để thôi diễn trận đồ và phát hiện Phản Ngũ Hành đại trận. Cấu trúc trận pháp hiện ra như một Âm Dương đồ, trong đó âm dương mắt đối xứng với nơi cây cắm rễ được cho là vị trí phong ấn Ngũ ma phong thiên loại. Vì đây là một trong ba hung trận hàng đầu cổ kim và chưa từng có người xâm nhập sống sót, Nhị trưởng lão quyết định chỉ dẫn mọi người đến quan sát từ xa."},{"chuong":1202,"tieuDe":"Đại Dược","tomTat":"Chiến hạm màu bạc đưa đoàn người của Thiên Thần Thư Viện tới một thung lũng được xác định là Âm Dương nhãn, nơi Ngũ Hành bản nguyên khí nồng đậm và vô số hài cốt nằm trong sương mù. Vì lo ngại Phản Ngũ Hành đại trận, các trưởng lão cho chiến hạm lui lại rồi dùng chiến ngẫu sét đánh của Ngũ Trưởng Lão tiến vào thăm dò. Chiến ngẫu và linh thân của Nhị Trưởng Lão đều không gặp nguy hiểm, qua đó xác nhận đại trận đã ngừng vận chuyển và đoàn người có thể tiến sâu vào cốc. Những văn khắc còn sót lại kể rằng cổ nhân từng lấy Ngũ hành đại lục làm lò, lấy năm tháng làm lửa để luyện một đại dược có khả năng phục sinh Tiên Vương, đồng thời lưu lại manh mối về hạt giống hoàn mỹ phối hợp phong ấn cự hung. Tam Trưởng Lão vẫn cảm thấy chân tướng có điểm kỳ quái vì một số cường giả trong cốc dường như đã tọa hóa khi tham ngộ chứ không bị trực tiếp sát hại. Tiên Viện sau đó đưa chiến thuyền tới, tuyên bố không nhường Tiên duyên nhưng đề nghị hai bên liên thủ mở Càn Khôn lô do hậu quả của việc khai lò không thể lường trước, và Nhị Trưởng Lão chấp thuận."},{"chuong":1203,"tieuDe":"Ẩn Giấu Cổ Địa","tomTat":"Các trưởng lão Tiên viện và Thiên Thần thư viện dựa vào chuẩn Thế Giới thụ trên Âm Dương nhãn để xác định rằng hẻm núi cùng vách đá chỉ là lớp che giấu một cổ địa chân thực. Ngũ trưởng lão và nhiều lão quái vật thử xuyên qua thạch bích nhưng đều bị trận pháp đánh bật, trong khi hai đệ tử trẻ lại vượt qua thuận lợi, giúp mọi người nhận ra cửa ải có liên quan tới phản Ngũ Hành và chuyên sàng lọc người tiến vào theo sức mạnh. Hai đệ tử trở về trong tình trạng bị thương, báo rằng bên trong có nhiều thiên địa linh túy và thần dược được phù văn nguy hiểm bảo vệ. Thạch Hạo, Yêu Nguyệt, Lục Đà cùng các cao thủ trẻ tuổi của hai viện sau đó đồng loạt tiến vào cổ địa. Tại vùng đất đỏ sẫm thiếu sinh cơ, họ phát hiện Dẫn hồn liên sắp trưởng thành, khiến Thạch Hạo, Lục Đà, Vương Hi và nhiều cường giả sở hữu ba đạo tiên khí lao vào hỗn chiến tranh giành. Sự xuất hiện của Phượng Hoàng thảo khiến một số người chuyển sang mục tiêu mới, nhưng cuộc chiến quanh Dẫn hồn liên vẫn tiếp diễn. Một nữ tử áo lam của Tiên viện chặn Thạch Hạo và dùng thân phận Tiên viện gây sức ép, song hắn không lùi bước, dọa thu nàng làm hầu gái rồi trực tiếp quyết đấu giữa đại hỗn chiến của các chí cường giả trẻ tuổi."},{"chuong":1204,"tieuDe":"Dẫn Hồn Liên","tomTat":"Nhiều chí tôn trẻ tuổi hỗn chiến quanh thần trì nơi Dẫn Hồn Liên cắm rễ, trong đó Thạch Hạo đối đầu một nữ đệ tử Tiên Viện còn Lục Đà giao chiến với một thanh niên tu thành ba đạo tiên khí. Thạch Hạo dùng lôi đình, Côn Bằng lực và những cành liễu vàng áp đảo nữ đệ tử Tiên Viện, sau đó lao về phía thần dược. Vương Hi, Lục Đà cùng người của Tiên Viện và Thiên Thần Thư Viện đồng loạt phong tỏa đường tiến, buộc hắn phải chống lại cả bảo thuật lẫn thần binh chứa tiên kim. Thạch Hạo kết hợp Bảo thuật Liễu Thần với Bảo thuật Lôi Đế, vận dụng Thái Âm lực bảo vệ bàn tay rồi hóa thành Côn Bằng thoát khỏi sát cục. Hắn tuyên bố sẽ ngăn bất kỳ ai hái sen, tạo ra thế giằng co khiến các bên không dám tiến trước. Sau đó Thạch Hạo chủ động xông vào vòng vây, dùng pháp lực miễn dịch làm hàng loạt bảo thuật tan biến và hóa giải những đòn tấn công trực tiếp bằng thần kiếm cùng cánh phượng tiên kim đảng. Cuối cùng, hắn vận dụng duy nhất động thiên phản công đám đông và bắt được Dẫn Hồn Liên."},{"chuong":1205,"tieuDe":"Đối Đầu Quần Hùng","tomTat":"Dẫn hồn liên thành thục rồi tan thành huyết thanh màu bạc có khả năng giúp nguyên thần vỡ nát Niết Bàn tái sinh, khiến quần hùng đồng loạt tranh đoạt. Thạch Hạo thu được toàn bộ huyết thanh nhưng pháp lực miễn dịch của hắn nhanh chóng mất hiệu lực dưới sự xung kích liên tục của phù văn và bảo thuật. Lục Đà, Vương Hi cùng ba cao thủ Tiên viện tiếp tục vây công, khiến Thạch Hạo bị Bình Loạn quyết làm bị thương và bị Phần Thiên diễm thiêu cháy lòng bàn tay. Hắn vận dụng Bảo thuật Liễu Thần, Côn Bằng pháp, Bảo thuật Lôi Đế và nhiều thần thông khác để chống trả, sau đó rút Đại La tiên kiếm thai chém đứt cánh phượng tiên kim đảng cùng thần kiếm của Vương Hi và hấp thu tiên kim trong hai binh khí. Thạch Hạo tiếp tục phối hợp kiếm thai với Lục Đạo Luân Hồi cổ thiên công, làm nữ đệ tử Tiên Viện và Vương Hi bị thương rồi phá khỏi vòng vây. Quần hùng lần lượt rút đi tìm thần dược khác, còn Thạch Hạo chuyển sang bám theo và chuẩn bị cướp những người tìm được bảo vật."},{"chuong":1206,"tieuDe":"Thần Dược Viên","tomTat":"Sau khi đoạt Dẫn Hồn Liên, Thạch Hạo tiếp tục tiến sâu vào cổ địa, nơi nhiều thần dược liên tiếp xuất thế và kéo các chí tôn trẻ tuổi vào những cuộc hỗn chiến. Một thiếu niên thanh tú của Tiên Viện đoạt Phượng Hoàng thảo, còn Thập Quan Vương dùng Long quyền cùng Cây non Thế Giới Thụ phá vòng vây, giành Nghiệt Long dược để chuẩn bị rèn luyện song quyền. Tại nơi Bát trân kỳ xuất hiện, Thạch Hạo giao phong trực diện với Lục Đà và đánh nứt gan bàn tay đối phương. Trong lúc đó, nhóm đệ tử thứ hai tiến vào cổ địa, khiến Thanh Y bị Mạnh Đô nhắm tới nhằm trả thù và kiềm chế Thạch Hạo. Thanh Y triệu vòng Thanh Nguyệt, mưa sáng Tiên đạo và Thần Diễm chống trả, làm người Tiên Viện liên tưởng tới truyền thuyết Thanh Nguyệt Tiên Tử. Phát hiện Thanh Y bị tấn công, Thạch Hạo lập tức tới cứu, dùng Côn Bằng quyền cùng nhiều bảo thuật đánh xuyên ngực Mạnh Đô. Mạnh Đô phải chạy khỏi cổ địa trước mặt trưởng lão hai viện, trở thành chí tôn trẻ tuổi đầu tiên bị buộc rút lui."},{"chuong":1207,"tieuDe":"Chân Kim","tomTat":"Mạnh Đô thất bại và suýt bị Thạch Hạo chém giết, khiến người Tiên Viện phải nhìn nhận lại sức chiến đấu cũng như nền tảng ba đạo tiên khí của hắn. Thanh Y bị Thanh Nguyệt dẫn vào trạng thái mê man, nhìn thấy một tiên tử tuyệt thế tiến vào thế giới nội tâm nhưng sau khi tỉnh lại vẫn phủ nhận khả năng tồn tại luân hồi chân chính. Trong cuộc tranh bát trân kỳ, một thanh niên Tiên Viện xé hỏng góc trận pháp và dùng Càn Khôn đại nhằm độc chiếm linh dược, song bị Bình Loạn Quyết của Vương Hi buộc phải ứng chiến. Thạch Hạo cùng nhiều chí tôn trẻ tuổi đồng loạt ra tay nhưng bát trân kỳ vẫn lợi dụng hỗn chiến để thoát khỏi vòng vây. Tế linh văn nguyên thủy sau đó bùng lên từ một ngọn núi thấp, khiến mọi người bỏ cuộc tranh dược và kéo tới ngôi miếu đổ nát cùng vách đá cổ. Thanh Y giải đọc được chỉ dẫn liên quan đến Ngũ Ma Phong Thiên Chủng và đường núi đá, trong khi Trích Tiên, Độc Cô Vân cùng hai cường giả Tiên Viện tiếp tục công kích các đồ án. Khi Độc Cô Vân nhỏ máu vàng lên vách đá, một sinh vật hung bạo phía sau hình khắc cánh cửa gầm vang rồi đưa bàn tay đầy lông ra ngoài, báo hiệu nó sắp xuất thế."},{"chuong":1208,"tieuDe":"Sinh Linh Bên Trong Vách Đá","tomTat":"Một cánh tay phủ lông đỏ tiếp tục thò ra từ cánh cửa khắc trên vách đá, trong khi sinh linh bên trong gầm lớn và cố vượt sang bên này. Độc Cô Vân ngăn các cao thủ Tiên Viện can thiệp, kết pháp ấn rồi dùng máu vàng kích hoạt những đường khắc trên cửa. Mạc Đạo nhận ra hắn và sinh linh đang sử dụng Bất Hủ chi ngữ, loại cổ ngữ chỉ số ít Hoàng tộc dị vực nắm giữ. Trích Tiên hiển hóa Chân Hoàng công kích Độc Cô Vân nhưng bị huyết khí vàng cùng bóng chiến thần chống lại, còn đòn đánh bằng cây non Thế Giới Thụ của Thập Quan Vương bị phù văn trên cửa chặn đứng. Khi máu vàng lấp đầy các đường khắc, sinh linh hình người phủ lông đỏ và có đôi mắt bạc bước hoàn toàn ra ngoài. Thanh Y nhờ cộng hưởng với Thanh Nguyệt mà hiểu được một phần cuộc đối thoại, từ đó tiết lộ Độc Cô Vân đang hỏi cổ lộ dẫn tới nơi nghỉ chân và nguyên quán của người bảo vệ một mạch. Những người có mặt vì vậy càng nghi ngờ mục đích, huyết mạch và sứ mệnh thật sự của Độc Cô Vân, nhưng chưa thể xác định hắn đang tìm tộc nhân hay phục vụ dị vực."},{"chuong":1209,"tieuDe":"Hoàng Tộc","tomTat":"Sinh linh lông đỏ dùng cổ ngữ hoàng tộc dị vực tranh luận với Độc Cô Vân về cố hương của dòng máu vàng, còn Thanh Y giải thích rằng người đã nhiễm hồng trần khí không thể quay về và việc mở giới môn có thể triệu gọi những cường giả đáng sợ. Độc Cô Vân đòi con đường từng được hoàng tộc ở thế giới bên kia hứa hẹn, nhưng đối phương từ chối nên hai bên giao chiến bằng thiên mâu và thần sóc, khiến hư không vỡ nát và nhiều tu sĩ quan chiến bị thương. Sau khi tách khỏi cuộc đấu, sinh linh lông đỏ bắt giữ ba tu sĩ của Thiên Thần thư viện và Tiên viện, giết họ rồi hút sạch sinh mệnh tinh khí để bù đắp cơ thể bị phong ấn lâu năm. Mạc Đạo nhận ra những mảnh vật chất bong khỏi hắn là chất lỏng do Bất Hủ giả tế luyện, có khả năng phong ấn vạn vật qua năm tháng dài đằng đẵng. Ông còn suy đoán sinh linh này thuộc một hoàng tộc cổ xưa dị vực và tiết lộ thiên loại tại đây từng khiến một bá chủ Bất Hủ tiếc nuối vì bỏ lỡ. Thạch Hạo liên hệ viên đạo chủng ấy với truyền thuyết Ngũ Ma phong thiên loại, trong khi Thanh Y cảnh báo các lò luyện đan có thể đang phong ấn cả một hoàng tộc với những trưởng bối và cường giả mạnh hơn chưa thoát vây."},{"chuong":1210,"tieuDe":"Hung Diễm Ngập Trời","tomTat":"Sinh vật lông đỏ cầm thần sóc giao chiến ngang sức với Độc Cô Vân, rồi dùng tin tức về cổ giới môn làm điều kiện yêu cầu giải phóng tổ tiên bị phong ấn. Độc Cô Vân khẳng định quyết trở về tổ địa, tắm trong Thánh hà màu vàng và hoàn thành nghi thức niết bàn của bộ tộc. Khi một tu sĩ phản đối, Huyền Côn đứng ra cứu viện nhưng bị hoa sen vàng áp chế, mất tay phải, bị chém ngang lưng và mất sức chiến đấu trước khi Độc Cô Vân ngăn đòn kết liễu. Sinh vật lông đỏ tiếp tục tiết lộ thiên loại trong bảo bình phía sau vách đá có thể giải phong các cao thủ bộ tộc, khiến Độc Cô Vân chấp nhận điều kiện tiến vào. Sau đó nó xuyên thủng một cao thủ Tiên Viện, ép Vương Hi giao chiến, làm nàng bị thương và lấy bảo huyết để phục vụ việc giải phong. Nhận ra Thanh Y hiểu cổ hoàng ngữ và mang khí tức Tiên đạo, nó chọn nàng làm mục tiêu kế tiếp. Thạch Hạo lập tức bước ra bảo vệ Thanh Y, tuyên bố đã chờ cơ hội giao chiến với Hoàng tộc dị vực từ lâu và lạnh lùng tự nhận là người sẽ giết đối phương."},{"chuong":1211,"tieuDe":"Cuồng Dã","tomTat":"Sinh linh lông đỏ khinh miệt Thạch Hạo sau khi liên tiếp đánh bại nhiều cao thủ, nhưng Hoang lập tức nổi giận và chủ động giao chiến. Thạch Hạo triển khai duy nhất động thiên cùng pháp lực miễn dịch, khiến pháp lực và thần thông của đối thủ tan rã rồi dùng Côn Bằng quyền cùng lôi điện liên tiếp đánh thẳng vào mặt hắn. Sinh linh lông đỏ vận chuyển khí huyết, làm Nguyên Thần phát sáng và tụng một loại cổ kinh để phá thế giam cầm. Thạch Hạo rút Đại La tiên kiếm thai chém vào mi tâm đối thủ, bổ mở tấm chắn ngũ sắc bằng tiên kim và để kiếm thai hấp thu tinh hoa của nó. Dù đã thoát khỏi giam cầm, sinh linh lông đỏ vẫn bị kiếm chém gần lìa đầu và phải mang thương thế nặng chạy vào thạch bích. Độc Cô Vân, Thạch Hạo, Thập Quan Vương, Trích Tiên cùng ngày càng nhiều tu sĩ lần lượt tiến vào truy theo."},{"chuong":1212,"tieuDe":"Đại Đạo Bảo Bình","tomTat":"Kim huyết của Độc Cô Vân mở cánh cửa phong ấn trên vách đá, khiến một nhóm học sinh tiến vào cổ địa trong khi những người khác quay về báo tin cho trưởng lão hai viện. Trong thế giới hoang vu phía sau vách đá, Thạch Hạo dùng Đại La tiên kiếm thai tiếp tục truy sát và gây thương tích nặng cho sinh linh lông đỏ, buộc nó chạy vào một vùng núi phủ sương. Qua Thiên mục, đoàn người phát hiện Đại Đạo Bảo Bình bằng đá lớn như núi nằm giữa quần sơn, vừa là lò luyện vừa là nơi phong ấn sinh linh Hoàng tộc dị vực từ thời Tiên cổ. Độc Cô Vân thi triển bí pháp xuyên không gian để vào trong, tuyên bố chỉ muốn tìm một đáp án nhưng vẫn rạch tay dùng kim huyết kích hoạt bảo bình. Sinh linh lông đỏ tiết lộ thiên loại nằm trong bình nhỏ tại miệng bảo bình và là mấu chốt duy trì phong ấn, đồng thời thừa nhận nó thoát ra được vì có cảnh giới thấp nhất. Theo chỉ dẫn của nó, Độc Cô Vân rải kim huyết lên quần sơn, khiến mỗi đỉnh núi mọc ra cây lớn mang hoa chứa sinh linh dị vực. Những sinh linh này hấp thu linh khí, mang theo chiến mâu và đại kích rồi đồng loạt nhảy khỏi hoa, phát động cuộc tấn công."},{"chuong":1213,"tieuDe":"Lịch Sử Tái Hiện","tomTat":"Trong cổ địa quần sơn, những cây khổng lồ nở hoa và phóng thích vô số sinh vật cổ mang thần binh, tái hiện cảnh đại chiến Tiên cổ. Đại Đạo Bảo Bình lần lượt ngưng tụ dấu ấn Tiên Binh và tiên kiếm để trấn áp đại quân, còn Trích Tiên cùng tu sĩ Tiên Viện nhận ra đây là dấu ấn lịch sử chân thực chứ không phải chiến sự đang xảy ra. Khi sức mạnh tháng năm bùng nổ, đoàn người phát hiện dấu ấn đang biến thành cạm bẫy thời gian Luân Hồi và vội rút lui. Quần sơn sau đó nứt vỡ, để lộ Mẫu Căn Hành của Mẫu Sào dị vực đang tìm cách tiếp nhận bảo huyết để giúp Bất Hủ bị phong ấn tái sinh. Bất Hủ dùng ma âm mê hoặc một số người hiến máu, nhưng tàn niệm hình người trên Đại Đạo Bảo Bình thức tỉnh, đánh thức họ và thiêu hủy phần rễ khổng lồ. Tàn niệm hé lộ rằng sinh linh dị vực chỉ là chất dinh dưỡng cho một viên thiên loại và tương lai sẽ có người đến thu hoạch nó. Độc Cô Vân truy hỏi chân tướng tổ tiên mang dòng máu vàng cùng con đường cổ xưa nhưng không được giải đáp, chỉ nhận lời cảnh báo rằng kỷ nguyên đã gần hồi diệt vong và mọi người phải chuẩn bị ứng kiếp."},{"chuong":1214,"tieuDe":"Vạn Đạo Thụ","tomTat":"Độc Cô Vân xin dấu ấn hình người công khai lai lịch thiên loại, nhưng đối phương tuyên bố hạt giống đã dành cho người khác rồi trở vào Đại Đạo Bảo Bình; Mẫu Căn Hành dùng để bồi dưỡng nó cũng cháy thành tro. Không còn hy vọng đoạt thiên loại, Thạch Hạo dùng Bảo thuật Lôi Đế truy kích sinh linh lông đỏ, buộc đối phương nhảy vào Đại Đạo Bảo Bình và biến mất trong huyết quang. Độc Cô Vân sau đó bị nghi cấu kết với dị vực, song mọi người quyết định giao hắn cho các trưởng lão xử lý vì thân phận hậu nhân người bảo vệ. Rời khu cổ địa, Thạch Hạo và Thanh Y thám hiểm đại lục Ngũ hành, thu đủ năm loại đạo chủng nhưng không thể trực tiếp hợp thành Ngũ hành tiên chủng. Chuẩn Thế Giới Thụ hoàng kim hấp thu Ngũ hành tinh khí, tiếp tục tiến hóa rồi nhổ rễ bay đi, khiến đoàn Thiên Thần Thư Viện và chiến thuyền Tiên Viện cùng bám theo tới một vùng pháp tắc thần bí. Sau khi thu hoạch các trái đạo tắc và tìm kiếm hơn hai mươi ngày, đoàn người phát hiện Huyền Không đảo ở cực tây với một cây giống cây trà mang hàng nghìn trái đại đạo, bị nghi là Vạn Đạo Thụ. Quy tắc thiên địa ngăn mọi người lên đảo, còn trong khe nứt hư không gần cây xuất hiện một cổ nhân bị xích sắt rỉ xuyên qua xương vai và khóa chặt."},{"chuong":1215,"tieuDe":"Kết Thúc Lữ Trình","tomTat":"Đoàn thám hiểm phát hiện Vạn Đạo Thụ mang hơn vạn trái quy tắc trên Huyền Không đảo và xác nhận đây là tiên chủng hoàn mỹ có thể hợp nhất với tu sĩ. Khi hai lão quái vật Tiên Viện định vượt Lôi Trì để lấy cây, sinh linh bị xích bên cạnh thức tỉnh, cảnh cáo mọi người rút lui rồi dùng máu, kiếm quang và uy thế áp đảo để phô bày sức mạnh. Những thi hài Tiên Thiên Thần Ma cùng chim thần quanh đảo khiến trưởng lão hai viện hiểu rằng tranh đoạt Vạn Đạo Thụ sẽ phải trả giá không thể gánh nổi, nên họ đành rời đi. Sau đó Chuẩn Thế Giới Thụ hoàng kim phá hư không, ngăn chiến hạm tiếp tục bám theo và chấm dứt vai trò dẫn đường. Đoàn người phải tự đi qua chiến trường cổ để tìm Huyết Chủng, quần thể kiến trúc chứa anh linh hạt giống và dòng sông có thời gian hạt giống, nhưng nhiều đệ tử chết vì cổ huyết, thi khí, đạo chủng phản phệ hoặc sức mạnh thời gian. Sau nhiều tháng thăm dò và liên tiếp gặp những hiểm họa có thể giết cả trưởng lão, đoàn thám hiểm ngừng tiến sâu, lên chiến thuyền rời Giới Phần và trở về Thiên Thần Thư Viện."},{"chuong":1216,"tieuDe":"Lộ Ở Phương Nào","tomTat":"Khi chiến hạm màu bạc rời Giới Phần, một tồn tại cổ xưa đang chịu phong ấn phóng hình chiếu bàn tay đen tập kích, khiến cả đoàn đứng trước nguy cơ bị tiêu diệt. Nhị Trường Lão tế Thập Giới Đồ chặn đòn rồi cùng các trưởng lão dùng tế đàn xương đưa mọi người trở lại Thiên Thần Thư Viện. Chuyến đi mang về nhiều đạo chủng nhưng hơn mười thiên tài đã chết hoặc mất tích, trong đó Dư Minh tử vong và Hoắc Mông mất tích. Không tìm được hạt giống hoàn mỹ, Thạch Hạo hỏi về việc dung hợp nhiều thiên loại nhưng được cảnh báo đó là tử lộ. Nhị Trường Lão suy đoán Tiên Viện còn giữ những vô thượng cổ loại có thể tái ngưng tụ, vì vậy yêu cầu Thạch Hạo, Vương Hi, Lục Đà và Yêu Nguyệt tạm hoãn dung hợp đạo chủng. Hai ngày sau, Tiên Viện dùng một tinh cầu đá làm pháp thuyền đưa Tiểu Thiên Vương cùng các đệ tử tinh anh tới thư viện. Thánh Viện cũng dẫn Tiểu Thánh và nhóm đệ tử mạnh nhất giáng lâm, mở ra cuộc hội tụ và cạnh tranh giữa anh tài ba viện."},{"chuong":1217,"tieuDe":"Thế Tới Ào Ạt","tomTat":"Tinh anh Tiên Viện và Thánh Viện cùng tới Thiên Thần thư viện để luận bàn và tuyển chọn những môn đồ xuất sắc, khiến các đệ tử đồng loạt xuất quan tìm kiếm cơ hội. Trong cuộc thương lượng với các trưởng lão, phía Tiên Viện tiết lộ họ có nhiều cực mạnh cổ chủng đào từ động phủ tiên gia của kỷ nguyên trước, nhưng những hạt giống này cần chân long huyết, phượng hoàng huyết hoặc máu của người tu thành ba đạo tiên khí để phục hồi hoàn mỹ. Nhị trưởng lão cùng các đồng viện tranh luận về quyền phân phối, buộc Tiên Viện cam kết dành ít nhất một cổ chủng cho thiên tài Thiên Thần thư viện và chọn người dựa trên chiến lực cùng tiềm năng. Đoàn Tiên Viện xuất hiện bằng một tinh cầu đá phủ hỗn độn khí, còn Thánh Viện tới trên cốt hồ lô bạch cốt khổng lồ. Yêu Nguyệt được tinh cầu đá đón vào, trong khi Vương Hi được cốt hồ lô của Thánh Viện mở thông đạo tiếp nhận giữa những lời bàn tán về vị hôn phu của nàng. Cùng lúc đó, mọi người dự đoán Nguyên Thanh và các mối ân oán cũ sẽ cản trở Thạch Hạo tiến vào hai viện. Cuối cùng, người Tiên Viện công khai gọi tên Hoang, cáo buộc chàng làm nhục Ngô Thái và đoạt Trạm Lam giáp trụ của Tiểu Thiên Vương, rồi ép chàng giao bảo vật và tới lĩnh tội. Thạch Hạo vẫn bình tĩnh quan sát khi toàn bộ ánh mắt trong Thiên Thần thư viện đổ dồn về phía mình."},{"chuong":1218,"tieuDe":"Phục Ma","tomTat":"Mười mấy đệ tử Tiên Viện xuất hiện tại Thiên Thần Thư Viện, ép Thạch Hạo nhận tội và giao Trạm Lam Giáp Trụ. Thanh Y cùng Mạc Đạo công khai đứng về phía hắn, bất chấp lời đe dọa rằng cả ba sẽ bị tước tư cách tiến vào Tiên Viện. Khi nam tử tóc tím tiếp tục nhục mạ và ra lệnh bắt người, Thạch Hạo từ chối chịu nhục rồi trực tiếp thách chiến. Nhóm đối phương phối hợp Hàng Ma xử, bảo bình và nhiều pháp khí để dựng Kim Cương Phục Ma trận. Thạch Hạo đồng thời vận dụng Thượng Thương, Luân Hồi và Chí Tôn thuật thứ ba chưa thành thục, hợp nhất ba lực rồi đánh tan cổ trận trong một đòn. Mười mấy người vận trận đồng loạt thổ huyết, còn hai kẻ cầm đầu bị hắn bắt sống. Thạch Hạo giẫm nát mặt nam tử tóc tím và đánh cô gái tóc bạc bay ngang, kết thúc cuộc hỏi tội bằng thất bại nhục nhã của nhóm đệ tử Tiên Viện."},{"chuong":1219,"tieuDe":"Tiểu Thiên Vương","tomTat":"Thạch Hạo tiếp tục trấn áp cô gái tóc bạc và nam tử tóc tím của Tiên Viện trước sự kinh ngạc của quần tu. Nam tử tóc tím âm thầm dùng Tử Kim Hàng Ma Xử tập kích, nhưng đòn đánh bị duy nhất động thiên ngăn lại, còn thần binh bị Thạch Hạo giẫm rạn nứt và mất thần năng. Thạch Hạo đánh nam tử tóc tím trọng thương, phá nát bảo bình phòng ngự của cô gái tóc bạc rồi chủ động dừng tay để tránh thực sự giết người. Tinh cầu đá của Tiên Viện sau đó tạo trường vực giam cầm trời cao, mở cửa và đưa hơn bốn mươi thiên tài trẻ bước ra trên cầu vồng bảy màu. Tiểu Thiên Vương xuất hiện với khí chất gần Chân Tiên, khiến Mạc Đạo thừa nhận không phải đối thủ và nhắc tới tỷ tỷ đã được Bất Hủ giả tiếp dẫn đi bồi dưỡng cùng Hoàng tộc. Cuối chương, Tiểu Thiên Vương hỏi Thạch Hạo về thu hoạch từ Trạm Lam Giáp Trụ, trong khi Yêu Nguyệt đứng cạnh hắn trên cầu vòm."},{"chuong":1220,"tieuDe":"Hùng Hổ Dọa Người","tomTat":"Tiểu Thiên Vương cùng Yêu Nguyệt và một nhóm tu sĩ Tiên Viện xuất hiện tại Thiên Thần Thư Viện, yêu cầu Thạch Hạo giao lại Trạm Lam Giáp Trụ. Thạch Hạo khẳng định chiến giáp là chiến lợi phẩm đoạt được quang minh chính đại sau khi Ngô Thái tấn công mình rồi thất bại, vì vậy hắn không chấp nhận khuất phục trước sự uy hiếp. Hơn mười đại thần thông từ đoàn người Tiên Viện đồng loạt đánh xuống, nhưng Thạch Hạo dùng cốt văn trong Nguyên Thủy Chân Giải lần lượt hóa giải. Tiểu Thiên Vương ngăn các tùy tùng tiếp tục gây rối, xác nhận chiến giáp là vật tùy thân cần dùng khi chinh chiến dị vực và tuyên bố mình đã dung hợp đạo chủng thành công. Không muốn trực tiếp lấy cảnh giới áp chế đối phương, hắn đề nghị cùng giải câu đố Tiên đạo hoặc để Thạch Hạo công kích tiên quang hộ thể của mình. Yêu Nguyệt lên tiếng hòa giải, song Thạch Hạo nhận ra các phương thức văn đấu đều có thể biến mình thành vật làm nền. Cuối cùng, hắn thách Tiểu Thiên Vương lên Thần Cấp võ đài để tiến hành một trận chiến công bằng."},{"chuong":1221,"tieuDe":"Thiên Thần Cảnh Đệ Nhất Nhân","tomTat":"Thạch Hạo từ chối phương án văn đấu và đề nghị dùng Thần Cấp võ đài để giao chiến đồng cảnh giới với Tiểu Thiên Vương. Tiểu Thiên Vương khéo léo từ chối vì vô thượng bảo chủng vừa dung hợp chưa ổn định, khiến ngay cả quy tắc võ đài cũng không thể áp chế cảnh giới của hắn. Trước sự chế giễu của người Tiên Viện, Thạch Hạo nhớ lại trận chiến với Trùng Đồng giả tại Hư Thần giới, khi hai người từng tạm thời đánh sụp chính loại võ đài này. Tiểu Thiên Vương gọi Vũ Vô Địch, đệ tử cuối của Đại trưởng lão Tiên Viện, tới thay mình xuất chiến và đưa Trạm Lam Giáp Trụ ra làm vật cược có điều kiện. Đoàn người Thánh Viện sau đó xuất hiện từ cốt hồ lô trắng, công khai phủ nhận danh hiệu đệ nhất của Vũ Vô Địch và thách thức Tiên Viện. Các lão quái vật quyết định cho phép cuộc tranh tài diễn ra, đưa một võ đài khổng lồ phủ tiên vụ tới giữa không trung. Thạch Hạo bị chuyển thẳng lên làm đài chủ, còn cốt văn trên võ đài xác nhận mục tiêu cuối cùng là chọn ra Thiên Thần cảnh đệ nhất nhân."},{"chuong":1222,"tieuDe":"Vô Địch","tomTat":"Các lão quái vật thuận thế biến xung đột giữa đệ tử ba viện thành cuộc tranh ngôi đệ nhất Thiên Thần cảnh, còn Thạch Hạo là người đầu tiên bước lên võ đài cổ. Thanh Y nhắc hắn cẩn thận, trong khi Vương Hi thừa nhận Hoang kinh tài tuyệt diễm và cảnh báo người Thánh Viện không được khinh địch. Theo lời Tiểu Thiên Vương, Vũ Vô Địch đại diện Tiên Viện đăng đài, mở đầu bằng lực lượng Thiên Phượng trong đôi mắt nhưng bị bảo thuật Liễu Thần của Thạch Hạo hóa giải. Đúng lúc ấy, chiến hạm chở nhóm Tào Vũ Sinh, Thái Âm Ngọc Thỏ và những người bạn cũ từ ba ngàn châu trở về, khiến bầu không khí quanh võ đài càng náo động. Vũ Vô Địch tiếp tục dùng Chân Hoàng bảo thuật hóa cổ Thiên Phượng bạc, còn Thạch Hạo diễn hóa Côn Bằng mang Âm Dương nhị khí để đối đầu, kết quả cả hai cùng bị đẩy lùi. Vũ Vô Địch sau đó chuyển niết bàn sinh cơ thành chín Phượng Hoàng sát kiếm mang tử khí, buộc Thạch Hạo dùng biển sét và chín thần binh chống trả. Hai cao thủ tiếp tục quấn lấy nhau trong dị tượng Lôi Đế và cổ Thiên Phượng, liên tục thay nhau chiếm thượng phong nhưng trận chiến vẫn chưa phân thắng bại."},{"chuong":1223,"tieuDe":"Quyết Đấu Đỉnh Cao","tomTat":"Thạch Hạo dùng Bảo thuật Lôi Đế quyết đấu Vũ Vô Địch đang thi triển cổ Thiên Phượng bí thuật, khiến hai bên liên tục gây thương tích cho nhau suốt hàng trăm chiêu. Vũ Vô Địch dựa vào lực niết bàn của Thiên Phượng để phục hồi, còn Thạch Hạo diễn hóa cây liễu vàng từ Bảo thuật Liễu Thần nhằm hấp thu tinh khí và chữa thương. Vũ Vô Địch sau đó vận chuyển Cửu Chuyển Thiên công, làm thiên địa đảo lộn và định nghiền nát đối thủ bằng đệ nhất chuyển. Thạch Hạo mở sáu môn hộ của Lục Đạo Luân Hồi, dẫn đi bí lực rồi đảo ngược đánh trả, buộc Vũ Vô Địch phải cắt đứt thế công. Khi hai cổ thiên công tiếp tục va chạm, cả hai cùng bị cuốn vào quy tắc do chính mình tạo ra, nhiều lần biến hóa, nghiền nát và tái sinh trước khi rơi vào tình trạng trọng thương. Cuối chương, Vũ Vô Địch hiện chân hình cổ thú chín đuôi và được người quan chiến nhận ra là Cửu U Ngao, một trong Thập Hung."},{"chuong":1224,"tieuDe":"Cửu U Ngao","tomTat":"Vũ Vô Địch lộ bản thể là hậu duệ Cửu U Ngao, dùng lông đỏ, sừng xám, vảy đen, tiếng gầm và chín đuôi đầu rồng đối chiến Thạch Hạo. Thạch Hạo triển khai các pháp môn Côn Bằng, lôi đình và duy nhất động thiên, nhưng vẫn bị đối thủ gây thương tích nặng trong cuộc ác chiến kéo dài hơn ba nghìn hiệp. Khi chín đầu rồng cắn trúng cơ thể, hắn để lộ đây là kế dụ địch, tái triển khai động thiên để cầm cố chúng rồi chặt đứt ba chiếc đuôi. Vũ Vô Địch dùng lực lượng Phượng Hoàng niết bàn khôi phục thân thể và bất ngờ mở Tử vong chi nhãn, phóng tử quang xuyên thủng Thạch Hạo. Thạch Hạo phối hợp Luân Hồi lực với Liễu Thần pháp ép tử quang ra ngoài, đồng thời khiến Cửu U Ngao thoái hóa thành hình dạng nhỏ như chó con. Hắn đạp đối thủ xuống võ đài, buộc phía Tiên Viện phải nhận thua và xin lưu mạng cho Vũ Vô Địch."},{"chuong":1225,"tieuDe":"Quét Ngang Đối Thủ","tomTat":"Cửu U Ngao trúng lực lượng Luân Hồi của Thạch Hạo, bị chuyển về hình thái ấu thú rồi đánh đến mất khả năng tiếp tục chiến đấu. Thạch Hạo nghe lời trưởng lão Thiên Thần Thư Viện và xét đại cục Cửu Thiên Thập Địa nên không giết đối thủ; khi thần thông hết hiệu lực, Cửu U Ngao hóa lại thành Vũ Vô Địch và lạnh lùng rời đi. Tiểu Thiên Vương giữ lời, tạm gửi Trạm Lam Giáp Trụ cho Thạch Hạo nhưng tuyên bố sẽ lấy lại khi hắn dung hợp đạo chủng và đạt cấp giáo chủ. Sau lời kích động trong bóng tối, nhiều đệ tử Thánh Viện bất chấp cảnh báo của Vương Hi, tranh nhau lên võ đài khiêu chiến. Xích Viêm dùng Tinh lực đại pháp và thân thể mạnh mẽ giao chiến hàng trăm hiệp, cuối cùng bị Thạch Hạo đánh sụp lồng ngực. Một cường giả có thành tựu ở Minh Văn cảnh và Liệt Trận cảnh tiếp tục xuất chiến nhưng cũng bị đá gãy xương. Ba người Thánh Viện khác lần lượt ra trận rồi đều bị đánh trọng thương, khép lại chuỗi chiến thắng áp đảo của Thạch Hạo."},{"chuong":1226,"tieuDe":"Tranh Cướp Thiên Tài","tomTat":"Sau khi năm cao thủ Thánh Viện và Vũ Vô Địch của Tiên Viện đều thất bại, không còn tu sĩ Thiên Thần cảnh nào dám lên lôi đài đối đầu Thạch Hạo, khiến hắn được ngầm coi là người mạnh nhất trong cùng cảnh. Thiên Thần Thư Viện sôi trào, còn Tào Vũ Sinh và Thái Âm Ngọc Thỏ công khai chế nhạo phía Tiên Viện. Giữa lúc được mọi người chúc mừng, Thạch Hạo phát hiện Nguyên Thanh đứng cạnh cao tầng Tiên Viện và phải cân nhắc nguy cơ đối phương lợi dụng quan hệ trong hai viện để cản trở mình. Tiên Viện và Thánh Viện nhanh chóng chuyển từ khiêu chiến sang tranh giành môn đồ sau khi biết Thiên Thần Thư Viện còn có nhiều mầm Tiên cùng những cơ duyên hiếm có. Thạch Hạo, Trích Tiên, Thập Quan Vương, Lục Đà, Huyền Côn, Mạc Đạo và Thanh Y lần lượt trở thành mục tiêu lôi kéo, trong đó Thanh Y được đặc biệt chú ý vì đã dung hợp Thanh Nguyệt. Khi được mời gia nhập Tiên Viện, Thạch Hạo hỏi thẳng mình sẽ nhận được loại cổ chủng nào và yêu cầu một hạt giống hoàn mỹ. Nhị Trưởng Lão cùng đại diện Thánh Viện vạch rõ các cổ chủng vô thượng đã có ứng viên, buộc lão quái vật Tiên Viện chỉ có thể hứa sẽ tìm thêm một hoàn mỹ hạt giống mà chưa thể bảo đảm kết quả."},{"chuong":1227,"tieuDe":"Lựa Chọn","tomTat":"Đại diện Tiên viện và Thánh viện tranh nhau chiêu mộ Thạch Hạo, nhưng cả hai bên đều phải thừa nhận những vô thượng cổ chủng và chân huyết thích hợp đã được phân phối cho người khác. Trong lúc ba viện phân lưu đệ tử, Thập Quan Vương, Trích Tiên, Lục Đà và Thanh Y chọn Tiên viện, còn Ninh Xuyên, Vương Hi cùng Tào Vũ Sinh đi theo Thánh viện. Hai viện dùng bạch cốt tế đàn liên lạc vực ngoại để xin thêm tài nguyên cho Thạch Hạo nhưng đều thất bại, chỉ có thể hứa những điển tịch và cơ duyên thay thế. Nhận thấy mình không được coi trọng ở mức tương xứng, Thạch Hạo chấp nhận đề nghị của Nhị trưởng lão và quyết định ở lại Thiên Thần thư viện để được bồi dưỡng đạo cơ. Sau khi tiễn các cố nhân rời đi, hắn gặp Đại trưởng lão trong rừng trúc tía và được cho mười ngày để tự xác định con đường tương lai. Thạch Hạo sau đó lấy cổ quan chứa ngọc thạch thư, thạch hạp thần bí và hạt giống hỗn độn chưa thành thục ra xem xét, suy đoán những kỳ vật này có liên hệ sâu sắc với con đường của mình."},{"chuong":1228,"tieuDe":"Lấy Thân Làm Chủng","tomTat":"Trong tử trúc lâm, Thạch Hạo xem xét kinh thư, Đại La tiên kiếm thai, Nguyên Thủy Chân Giải và hạt giống hỗn độn chưa thành hình để cân nhắc con đường tu hành tương lai. Không cam lòng chỉ chọn cổ pháp hoặc pháp đương thời, hắn quyết định theo đuổi cả hai nhằm có đủ sức đối đầu dị vực và bảo vệ những người thân cận trong đại kiếp. Thạch Hạo đến vùng đầm lầy thỉnh giáo Đại trưởng lão, đúng lúc ông dùng thánh dược câu được Bát trân quy rồi thả nó trở lại vì đó không phải sinh linh bí ẩn mà ông tìm kiếm. Qua cuộc trò chuyện, hắn biết dưới Thiên Thần Thư Viện có một tiên gia động phủ chưa mở, thông với vùng đầm lầy và ẩn giấu một sinh linh giảo hoạt. Đại trưởng lão kiểm tra hạt giống của Thạch Hạo, xác nhận nó rất quý giá nhưng chưa thành hình, vẫn đang thai nghén thiên địa tạo hóa. Ông sau đó trình bày con đường lấy chính thân thể làm đạo chủng, tế luyện chân ngã để thân thể thành đạo và Nguyên Thần quy nhất. Tuy nhiên, con đường này đã đứt đoạn từ Tiên Cổ vì những người từng thử đều thất bại, hoặc trở thành phế nhân, hoặc tự luyện chết mình."},{"chuong":1229,"tieuDe":"Lộ Ở Phía Trước","tomTat":"Đại trưởng lão giải thích rằng lấy thân làm chủng là một con đường gần như đã bị cắt đứt, từng khiến phần lớn thiên tài thử sức chết hoặc tàn phế, nhưng Thạch Hạo vẫn kiên quyết lựa chọn để tránh trở nên tầm thường. Ông trao cho Thạch Hạo một chồng ngọc thạch thư tổng hợp suy diễn và kinh nghiệm của nhiều thế hệ, đồng thời cho biết hạt giống kỳ dị như cuống rốn thiên địa mà hắn đang giữ có thể nâng cao hy vọng thành công. Sau ba ngày nghiên cứu, Thạch Hạo hiểu những tài liệu này mới chỉ dẫn phương hướng và hắn còn phải đối diện các dị tượng quỷ dị từng khiến nhiều người ngã xuống. Đại trưởng lão chuẩn bị phần lớn thần phẩm bảo hộ, còn Thạch Hạo góp Dẫn hồn liên, Thiên thần thụ và Phục sinh thảo lấy từ di tích Tiên cổ. Hai vật còn thiếu là Trừ tà thần trúc ít nhất hai mươi tiết và Hoàng tuyền quả sinh trưởng hơn chín nghìn năm tại nơi cực âm, nên Thạch Hạo phải tự tới một cổ địa đặc biệt để hái thuốc, luyện thân và rèn nguyên thần. Đại trưởng lão cũng tiết lộ bản thân từng thất bại trên con đường lấy thân làm chủng nhưng sống sót nhờ một cơ duyên. Cuối cùng, ông nhắc tới Hợp Đạo hoa, kỳ hoa có thể bảo đảm Thạch Hạo thành công và thậm chí cứu hắn sống lại nếu thất bại đến mức tàn phế nhưng vẫn còn một hơi."},{"chuong":1230,"tieuDe":"Chỗ Cần Đến","tomTat":"Đại trưởng lão giải thích cho Thạch Hạo về Hợp Đạo Hoa, một kỳ hoa có thể giúp sinh linh trực tiếp hợp đạo nhưng chỉ để lại manh mối mơ hồ liên quan đường thành tiên và chốn Cửu U. Ông truyền Chuy Cốt Pháp cùng Đoán Thần Pháp để Thạch Hạo rèn luyện xương thịt và nguyên thần trước cửa ải sống còn, đồng thời chỉ rõ phần truyền thừa tiếp theo nằm tại Thánh viện và Tiên viện. Sau khi lĩnh hội, Thạch Hạo một mình rời Thiên Thần thư viện, vừa tu luyện vừa vượt qua nhiều cự thành của Vô Lượng Thiên để tìm Trừ tà thần trúc và Hoàng tuyền quả. Ngọc bài do Đại trưởng lão ban dẫn hắn tới Tiên Khâu, ngọn núi cao mười vạn trượng ẩn trong hư không mà người không có tín vật không thể nhìn thấy hay chạm tới. Thạch Hạo mất nửa tháng chống lại áp lực khủng khiếp để leo hơn chín vạn chín nghìn bậc, khiến nhiều đoạn xương nứt vỡ và trực tiếp cảm nhận tác dụng của Chuy Cốt Pháp. Trên đỉnh núi, hắn gặp Huyền Không Tự cùng nhiều sinh linh cổ xưa mang khí tức đáng sợ đang ngồi ngộ đạo. Cuối cùng, Thạch Hạo triệu ra thần bàn và cổ hỏa mang tiên vụ cùng Hỗn Độn khí để chiếu rọi họ, bắt đầu khắc họa các dấu ấn Đại đạo."},{"chuong":1231,"tieuDe":"Chiến Thần Lạc Ấn","tomTat":"Thạch Hạo tiến đến cổ miếu màu vàng trên đỉnh núi, ngồi sau những lạc ấn Đại Đạo cổ đại và dần hòa vào khí cơ của khu vực Chiến thần lạc ấn. Tiếng tụng kinh cùng Đại Đạo liên điều liên tục đánh nát toàn bộ xương cốt, khiến hắn phải cưỡng ép giữ thân thể tụ lại và vận chuyển Chuy Cốt Pháp để tái đúc Thần cốt. Trong lúc hắn chịu lễ rửa tội kéo dài mười ngày, trưởng lão Tiên Viện đưa đệ tử lên núi bằng chiến thuyền và phát bạch cốt phù để giảm áp lực. Đoàn Thánh Viện cũng tới nơi, còn Yêu Nguyệt, Tào Vũ Sinh, Vương Hi và tu sĩ hai viện đều kinh ngạc khi nhận ra người trong kim vụ là Hoang từng đánh bại Cửu U Ngao. Phần lớn tu sĩ không thể tiếp tục chịu đựng lạc ấn nên rời đi tìm cơ duyên tại Tiên Khâu. Sau khi hoàn thành quá trình chuyển hóa xương, Thạch Hạo được các trưởng lão khuyên tranh thủ lúc đạo cốt chưa khép lại để tìm Ích Tà Thần Trúc ngao luyện thân thể. Hắn bước lên Hư Không Thần Kiều, vượt qua những tu sĩ bị cảm xúc của anh linh cổ đại làm phát cuồng rồi tiến vào một bí cảnh."},{"chuong":1232,"tieuDe":"Như Giẫm Trên Đất Bằng","tomTat":"Trong Tiên khâu, các dấu ấn anh linh liên tục tác động nguyên thần khiến nhiều đệ tử Tiên Viện và Thánh Viện đau đớn hoặc mê loạn, nhưng Thạch Hạo dùng khí huyết, cốt tủy màu vàng và Đại La Tiên Kiếm để đẩy lui chúng. Một anh linh còn linh giác nhận ra thanh kiếm và kinh hãi vì nó vẫn tồn tại trên đời. Thạch Hạo tiếp tục mở Duy nhất động thiên, vượt qua tràng vực trước sơn môn gần như đi trên đất bằng và buộc Vương Hi phải nhường con đường hẹp. Hắn dùng một quyền phá thần môn màu vàng mà những thiên tài tới sau không thể lay chuyển, rồi tiến vào khu vực sâu hơn. Sau khi xua một quái điểu anh linh bằng Đại La Tiên Kiếm, hắn gặp lão nông vốn là bức họa trên vách đá đã sinh linh tính. Lão nông cảnh báo thử thách phía trước sẽ tạo áp lực tương ứng với cảnh giới của từng người, nhưng Thạch Hạo vẫn quyết định tiếp tục. Cuối cùng, hắn nhìn thấy cây Trừ tà thần trúc cổ xưa nhất trên đỉnh núi, với thân trắng như tuyết và hỗn độn sấm sét bao quanh."},{"chuong":1233,"tieuDe":"Xông","tomTat":"Thạch Hạo kiên quyết tiếp tục tiến về phía Ích Tà Thần Trúc sau khi lão nông không dám đi tiếp và trở lại thành hình khắc trong vách núi. Hắn trước tiên bị anh linh dơi đỏ mắt vàng hóa thành chiến mâu tập kích, khóa cứng thân thể và thần hồn, nhưng đã dùng nguyên thần cùng Đại La Tiên Kiếm phá vỡ áp chế và ép đối phương bỏ chạy. Khi băng qua khoảng đất cháy dưới chân núi, hắn bị vô số tàn hồn vây đánh và xâm nhập cơ thể, phải dựa vào kiếm thai cùng giáp trụ rách của Lôi Đế mới sống sót. Tiếp đó, Thạch Hạo giao chiến thể phách với khôi lỗi Kim Cương tộc, chịu thương thế gần như tan thân rồi đánh nát nó, song chứng kiến đối thủ tự tái tạo và trở lại tảng đá. Trên đỉnh núi, hắn gặp khôi lỗi hình người hoàn toàn bằng Hắc Ám tiên kim và biết được nó từng theo một Bất Hủ giả từ thế giới bờ bên kia tới đây. Dấu ấn trên đá tím sau đó hiện ra Bất Hủ giả, người tự nhận bản thân chính là quỷ dị và chẳng lành. Cuối cùng, Thạch Hạo tới được cây thần trúc có khả năng khắc chế nguyền rủa, đồng thời phát hiện chất lỏng trắng từ đốt trúc đang tích tụ thành một ao thần dịch dưới gốc."},{"chuong":1234,"tieuDe":"Con Đường Duy Nhất","tomTat":"Thạch Hạo tiến đến khu vực Ích Tà Thần Trúc, nhìn thấy ao thần dịch dưới rễ cây và dấu ấn tuyệt vọng của một Bất Hủ sinh linh trên vách đá tím. Hắc Ám tiên kim nhân xuất hiện ngăn đường, còn quy tắc cửa ải buộc hắn phải cất Đại La Tiên Kiếm và dùng chân thân trọng thương giao chiến. Côn Bằng pháp, Lôi Đế bí thuật, Luân Hồi thần thông cùng Lục Đạo Luân Hồi thiên công đều không thể triệt để phá hủy con rối có khả năng hóa lỏng, tái tổ hợp và thích nghi. Ý chí cổ xưa tuyên bố người vượt ải phải siêu việt tiên hiền và Chí Tôn cùng cảnh thì thế giới này mới có hy vọng chống lại Dị Vực. Trong trận chiến, Thạch Hạo phát hiện tảng đá xanh ghi lại việc một người trẻ tuổi Hoàng tộc Dị Vực từng miễn cưỡng vượt ải và lấy thần dịch luyện thể vào cuối kỷ nguyên trước. Được dấu tích ấy khích lệ, hắn nén động thiên duy nhất cùng các dấu ấn bảo thuật vào cơ thể, khiến chùm sáng hóa thành luân bàn đánh bay và làm tiên kim nhân rạn nứt. Thạch Hạo tiến về phía ao thần dịch trong trạng thái ngộ đạo, nhận ra đây là khởi đầu cho con đường của riêng mình."},{"chuong":1235,"tieuDe":"Thần Trúc Trì Ngộ Đạo","tomTat":"Thạch Hạo chìm trong huyền cảnh, áp súc duy nhất động thiên vào bụng thành luân bàn sinh tử và bản năng bộc phát sức mạnh đánh văng Hắc Ám tiên kim nhân đang tập kích. Sau khi đối thủ bị nứt vỡ rồi biến mất, hắn tiếp tục xem thân thể như một thế giới, khắc cốt văn cùng quy tắc bảo thuật lên cực điểm màu vàng và tìm cách cân bằng sinh khí với tử khí. Những lần thử nghiệm khiến bụng hắn suýt nổ tung, nhưng thần dịch trong thần trì Ích Tà Thần Trúc liên tục chữa lành thương thế, rèn luyện xương và thúc đẩy thể chất tiến hóa. Thạch Hạo lần lượt hình thành rồi tản Âm Dương sinh tử đạo đồ, biến tử khí thành biển chết và sinh khí thành dòng suối sinh mệnh để khảo nghiệm sự kết hợp giữa hai lực. Từ đó, hắn bước đầu tìm ra con đường mở Thần Tàng trong thân thể, có tiềm năng phát triển thành một hệ thống tu luyện hoàn toàn mới. Sự lĩnh ngộ lập tức dẫn tới thiên phạt khủng bố, xuyên thủng thân thể và đánh nát xương cốt vừa tái tạo. Thạch Hạo không tuyệt vọng mà vui mừng vì xem lôi kiếp là bằng chứng cho giá trị của con đường mới, trong khi thần dịch tiếp tục thấm vào xương vỡ và cốt tủy để duy trì quá trình tái sinh."},{"chuong":1236,"tieuDe":"Tàn Khốc Lột Xác","tomTat":"Thiên phạt nhiều màu liên tục xuyên thủng huyết nhục, đánh gãy xương và đẩy Thạch Hạo đến sát bờ hình thần俱 diệt, trong khi chất lỏng Ích Tà Thần Trúc cùng cốt tủy vàng cố duy trì sinh cơ cho hắn. Sau khi những bảo thuật đối kháng không đủ hiệu quả, hắn dẫn sinh khí của thần trúc và tử khí do lôi điện tạo thành vào Động Thiên duy nhất, dựng Âm Dương sinh tử đạo đồ để nghịch chuyển sinh tử nhưng suýt khiến cả đạo đồ lẫn Động Thiên nổ tung. Thạch Hạo nhận ra tâm thế chỉ muốn né tránh hoặc hóa giải thiên phạt đã làm mình mất đi nhuệ khí, vì vậy khôi phục niềm tin tất thắng và chuyển sang chủ động đối kháng. Ý chí dâng cao khiến Chí Tôn huyết sôi trào và loại phù văn Chí Tôn trời sinh thứ ba hiện hóa, tạm thời nâng mạnh sinh mệnh lực, uy lực cùng tinh khí thần của hắn. Hắn vận dụng Chuy Cốt Pháp triệu hồi các mảnh xương vỡ, dùng lôi điện và thần dịch nối lại rồi tái tạo toàn bộ cốt thể, khiến cốt tủy chuyển từ vàng sang đỏ và xương trở nên trắng muốt, cứng rắn hơn. Khi lôi kiếp suy yếu, Thạch Hạo chủ động thôn phệ lôi quang, hấp thu sinh cơ ẩn trong sức hủy diệt và hoàn thành một lần lột xác tàn khốc."},{"chuong":1237,"tieuDe":"Sinh Mệnh Phồn Thịnh","tomTat":"Sau khi sống sót qua lôi kiếp, Thạch Hạo hoàn thành một lần lột xác lớn về xương cốt, thể chất và cấp độ sinh mệnh nhờ sấm sét cùng thần dịch Ích Tà Thần Trúc. Sức mạnh thân thể của hắn tăng tới mức một quyền không dùng thần lực cũng đủ đánh chết Thiên Thần, đồng thời một luồng khí tức tinh khiết hòa vào máu thịt khiến hắn liên tưởng đến khả năng chống nguyền rủa và lực lượng không rõ. Hắn thu gom phần thần dịch còn lại rồi rời vùng núi để tiếp tục tìm Hoàng Tuyền Quả, trong khi Yêu Nguyệt, Vương Hi và các thiên tài bên ngoài sơn môn quyết định liên thủ phá giới bích. Dọc theo dòng sông màu vàng, Thạch Hạo vượt qua một cây cầu đá cổ và phát hiện thung lũng chứa năm, sáu thi thể khổng lồ tỏa ánh sáng thần thánh. Khi bí bảo cấp Thiên Thần vừa chạm màn sáng bảo vệ đã tan nát, hắn kiềm chế lòng tham và chủ động rút lui. Cuối cùng, Thạch Hạo đến cuối dòng sông, nhìn thấy ba cây thực vật màu vàng và xác định một cây đang kết Hoàng Tuyền Quả. Việc hắn tiếp cận linh quả mà không gặp ngăn cản khiến tình thế trở nên thuận lợi khác thường."},{"chuong":1238,"tieuDe":"Hoàng Tuyền","tomTat":"Thạch Hạo định hái những trái vàng bên dòng sông nhưng kịp nhận ra bốn Hoàng Tuyền Trùng đang ngụy trang thành cành cây và tránh được cuộc phục kích. Những biến chủng danh trùng này cắn xuyên màn sáng phù văn, phun quang vụ ăn mòn không gian và dùng tơ trắng trói các chim thần do Pháp môn Côn Bằng diễn hóa. Thạch Hạo lần lượt vận dụng Bảo thuật Liễu Thần, Pháp môn Côn Bằng, Bảo thuật Lôi Đế cùng động thiên bộc phát để chống trả, đồng thời nhận ra Côn Bằng pháp có khả năng khắc chế thiên tính đối với loài trùng. Hắn giết con đầu tiên bằng sức bộc phát của động thiên, chém con thứ hai bằng Đại La Tiên Kiếm và nghiền nát con thứ ba nhờ xương cốt từng được Ích Tà Thần Trúc rèn luyện. Dù thoáng nghĩ Hoàng Điệp sau khi thức tỉnh có thể hiệu lệnh loài trùng này, hắn vẫn bắt rồi băm nát con cuối cùng để ngăn nó sống lại. Sau trận chiến, Thạch Hạo phát hiện hai cây thuốc còn tổng cộng tám Hoàng Tuyền Quả và hái một quả để dùng thử. Dược lực hội tụ tại mi tâm, kích thích tinh thần lực và làm nguyên thần tăng trưởng, khiến hắn lập tức triển khai Rèn thần pháp để tận dụng cơ hội."},{"chuong":1239,"tieuDe":"Triệt Ngộ","tomTat":"Dược lực của Hoàng Tuyền Quả khiến Nguyên Thần Thạch Hạo ly thể thành một tiểu nhân được ba đạo tiên khí quấn quanh, tự tụng kinh và hấp thu hàm nghĩa của thiên địa. Nhờ tích lũy tu hành cùng lần xúc phát này, hắn triệt ngộ Nguyên Thủy Chân Giải, hiểu rằng đó là pháp cổ điển giúp giản hóa huyền bí, tiếp cận bản chất càn khôn và thúc đẩy khả năng vận dụng các thần thông khác. Sinh linh giống hắn trên một đóa đại đạo chi hoa cộng hưởng với Nguyên Thần, khiến hắn có cảm giác như trải qua luân hồi và từng học vạn pháp. Hoa văn của Nguyên Thủy Chân Giải bóc khỏi Nguyên Thần rồi khắc về phía sinh linh ấy, trong khi các pháp khác cũng bắt đầu diễn biến tương tự trước khi Thạch Hạo tỉnh lại. Sau lần giác ngộ, hắn cảm nhận rõ khả năng khống chế các pháp đã tăng mạnh, nhưng vẫn phải tiếp tục lưu lại để hoàn tất quá trình lột xác Nguyên Thần. Trong trạng thái mơ màng, khí lạnh âm trầm đánh thức hắn và để lộ dòng sông vàng mang tử khí chảy qua đại địa phủ xương. Ở cuối dòng sông, Thạch Hạo nhìn thấy đoạn nhai cùng miệng núi lửa tối như Địa ngục, qua đó nhận ra Hoàng Tuyền Quả còn ẩn chứa một mặt đáng sợ."},{"chuong":1240,"tieuDe":"Địa Ngục","tomTat":"Sau khi dùng Hoàng Tuyền Quả, Thạch Hạo xuất hiện giữa một thế giới tử vong vô tận phủ đầy hài cốt và bay tới vực sâu ở cuối đại địa để thăm dò. Qua Thiên Nhãn thông, hắn nhìn thấy Ma thần, ác quỷ cùng dung nham bên trong trước khi vực sâu bạo động, nuốt cả núi non, xương cốt và chính hắn xuống cõi ngầm. Tại biển dung nham dưới lòng đất, Thạch Hạo chứng kiến một sinh linh mang Tiên Đạo khí tức bị năm sợi xích phân thây rồi kéo chìm hoàn toàn. Một đảo bạch cốt sau đó nổi lên, khóa cổ cùng tứ chi hắn và thi hành hình phạt tương tự, khiến huyết nhục bị dung nham thiêu sạch. Khi chỉ còn bạch cốt trong cảm nhận, Thạch Hạo bình tĩnh nhận ra đây là tác động tinh thần do Hoàng Tuyền Quả tạo ra để rèn Nguyên Thần và ý chí. Dù tiếp tục bị tiên kiếm xuyên thủng mi tâm, đóng đinh Nguyên Thần và đẩy vào bóng tối, hắn vẫn không khuất phục mà chủ động yêu cầu Địa ngục tiếp tục thử thách để mình trở nên mạnh hơn."},{"chuong":1241,"tieuDe":"Bốn Đạo Luân Hồi Ấn","tomTat":"Thạch Hạo bị cuốn vào cảnh Địa Ngục do Hoàng Tuyền quả tạo ra, cảm nhận thân thể và nguyên thần tan vỡ rồi hoàn toàn mất ý thức. Hắn tỉnh lại dưới dạng một đám hồn hỏa trên đảo bạch cốt và nhờ kiếm thai, Lôi Đế áo giáp cùng những khối xương truyền thừa mà dần nhớ ra mình là Hoang, là Thạch Hạo. Sau quãng thời gian dài tưởng như hàng trăm năm, hắn chấp nhận rằng mình đã chết và đau đớn nhớ về thân nhân, bằng hữu. Giọng nói vô tình gọi Luân Bàn chuyển sinh, đưa hắn mang ký ức trải qua bốn đời sinh, lão, bệnh, tử trong những thế giới khác nhau. Khi trở về và tỉnh lại bên ba cây Hoàng Tuyền quả, Thạch Hạo phát hiện nguyên thần đã tăng vọt vượt xa mức thông thường của Thiên Thần cảnh. Trong lòng bàn tay hắn đồng thời xuất hiện bốn đạo Luân Hồi Ấn, tương ứng chính xác với bốn lần chuyển thế. Ghi chép cổ xem loại ấn ký này là chứng cứ cho Luân Hồi của số ít tuyệt đại thiên kiêu, khiến Thạch Hạo không thể xác định trải nghiệm vừa qua chỉ là đại mộng hay một cuộc chuyển sinh chân thực."},{"chuong":1242,"tieuDe":"Anh Linh An Nghỉ","tomTat":"Thạch Hạo tỉnh lại nguyên vẹn sau trải nghiệm Hoàng Tuyền Quả, nhưng phát hiện bốn đạo Luân Hồi ấn chân thực trong lòng bàn tay trái. Sau khi suy xét về chuyển sinh, Nguyên Thần ly thể và hồn chủng của Thanh Y, hắn tạm gác bí mật Luân Hồi để chuyên tâm trở nên mạnh hơn. Nguyên Thần của hắn đã vượt xa Thiên Thần thông thường, còn cốt văn Nguyên Thủy Chân Giải tự kết thành giáp trụ bảo hộ, khiến thân thể và tinh thần cùng đạt trạng thái đỉnh cao hiện tại. Hắn thu bảy viên Hoàng Tuyền Quả còn lại, dự định tặng người khác nhưng sẽ tự mình hộ pháp để tránh họ trầm luân trong trải nghiệm. Đi sâu vào Tiên khâu, Thạch Hạo gặp lại lão nông và biết nơi đây là cổ táng địa có vô số anh linh, kể cả những tồn tại màu vàng mang Tiên Đạo khí tức, đang bị tờ giấy vàng chữ Phong trấn áp. Lão nông cho biết hậu thế có thể giải phong đội quân này để tham chiến, song họ có nguy cơ không phân biệt địch ta, đồng thời tiết lộ một Chí Tôn anh linh từ kỷ nguyên Tiên cổ còn ngủ sâu dưới cổ địa. Thạch Hạo ghi nhớ bí mật, chấp nhận sẽ quay lại giải phong nếu đại cục cần thiết, rồi rời Tiên khâu để trở về Thiên Thần Thư Viện tu hành theo con đường lấy thân làm chủng."},{"chuong":1243,"tieuDe":"Loạn Thời Đại","tomTat":"Trên đường rời sơn môn, Thạch Hạo gặp các tu sĩ Tiên Viện và Thánh Viện, nhưng chỉ thừa nhận mình có chút thu hoạch khi bị dò hỏi về Ích Tà Thần Trúc. Một thanh niên Tiên Viện dùng Ngũ hành thần kiếm chém đá để thị uy, liền bị Thạch Hạo dùng một kiếm chém rơi kim quan và cảnh cáo không được tùy tiện chĩa kiếm vào mình. Sau khi hắn rời đi, Vương Hi, Yêu Nguyệt và những người khác cho rằng việc thiếu hoàn mỹ cổ chủng sẽ khiến hắn mất ưu thế sau Thiên Thần cảnh. Thạch Hạo sau đó gặp Tào Vũ Sinh đang nghiên cứu ký ức cổ chiến hồn để học cổ pháp, đồng thời khiến người này từ bỏ ý định lập tức ăn Hoàng Tuyền Quả. Thái Âm Ngọc Thỏ bất ngờ giành lấy quả rồi ăn, khiến nguyên thần biến mất và thân thể cứng ngắc, buộc Thạch Hạo cùng Tào Vũ Sinh canh giữ suốt một ngày một đêm. Nàng bị bóng tối cuốn đi trong chốc lát rồi trở lại, mang theo vết thương như dấu ấn bị xóa và ký ức mơ hồ về chiếc mâm vãng sinh, một chiếc đỉnh cửu sắc đẫm máu vượt thời gian cùng bóng người quen thuộc. Nhận ra nhiều yếu tố từ quá khứ và hậu thế đang đan xen trong kỷ nguyên hiện tại, Thạch Hạo yêu cầu nàng dùng thần niệm tái hiện toàn bộ trải nghiệm để hắn tự mình kiểm tra."},{"chuong":1244,"tieuDe":"Chú Ý","tomTat":"Qua thần thức của Thái Âm Ngọc Thỏ, Thạch Hạo nhìn thấy nữ tử áo trắng cùng ba nam tử mơ hồ điều động một đại đỉnh đầy vết máu vượt qua vách ngăn đại thế giới và dòng sông thời gian. Thái Âm Ngọc Thỏ tỉnh lại nhưng chỉ nhớ được lời nói về một người cô độc từng vượt giới hải, đi xuyên hắc ám và hóa giải quỷ dị, còn phần ký ức quan trọng đã bị thời gian xóa mờ. Thạch Hạo chia thần dịch Ích Tà Thần Trúc cho đồng bạn, tặng Tào Vũ Sinh một viên Hoàng Tuyền Quả rồi cùng mọi người rời bí cảnh Tiên khâu. Trên đỉnh núi, hắn từ chối lời mời của Tiên Viện vì không có cổ chủng hoàn mỹ phù hợp, đồng thời không vào Thánh Viện do các cơ duyên lớn đã được phân phối cho những người kế nhiệm được chọn trước. Nhờ thể phách được thần dịch gột rửa và thành quả ngộ đạo, hắn nhanh chóng xuống hết mười vạn bậc thang, khiến nhiều cường giả kinh ngạc và có người bắt đầu hối hận vì từng bỏ qua hắn. Trở về Thiên Thần Thư Viện, Thạch Hạo giao Ích Tà Thần Trúc cùng Hoàng Tuyền Quả cho Đại trưởng lão và quyết định bế quan đi con đường lấy thân làm chủng. Đại trưởng lão chuẩn bị dược trì, đại đỉnh và lão dược, đồng thời cảnh báo quá trình có thể kéo dài từ vài tháng đến hơn mười năm. Tin tức bế quan nhanh chóng truyền đến các Trường Sinh gia tộc và thiên tài hai viện, khiến ngoại giới đồng loạt chờ xem Thạch Hạo sẽ suy thoái hay mở ra một thời kỳ huy hoàng mới."},{"chuong":1245,"tieuDe":"Con Đường Lột Xác Tê Cả Da Đầu","tomTat":"Trong khi ngoại giới bàn tán và nhiều người chờ Thạch Hạo thất bại vì không có vô thượng cổ chủng, Thanh Y lo lắng còn Tào Vũ Sinh tin hắn sẽ không dễ chết. Tại Thiên Thần Thư Viện, Thạch Hạo điều chỉnh thân thể và Nguyên Thần tới trạng thái đỉnh cao trước khi được Đại trưởng lão đưa vào đợt rèn luyện khắc nghiệt. Hắn ngâm trong dược trì chứa thần dược và khoáng liệu quý, chịu Tiên huyết tinh sa nóng chảy cùng đao khí chém vào xương tủy, rồi vận dụng Chuy Cốt Pháp để hoàn thiện thể phách. Sau mười ngày tôi luyện và một ngày một đêm ngâm thần dịch Ích Tà Thần Trúc, hắn phục hồi hoàn toàn và mạnh hơn trước. Thạch Hạo tiếp tục bước vào dược trì thứ hai, chủ động chịu bạch ngọc hạt cùng nhiều độc trùng Thần cấp truyền độc suốt mười ngày mười đêm để rèn huyết, gân, xương và da. Đại trưởng lão xác nhận hắn đã bước lên con đường lấy thân làm chủng, dù vẫn chưa tiến hành bước lột xác then chốt và còn phải đạt cực đỉnh trong Thiên Thần cảnh. Cùng lúc đó, Tiên Viện và Thánh Viện đều có tuyệt thế kỳ tài hoàn thành đột phá bằng cổ chủng, huyết lực quý hiếm, sự hợp nhất mười động thiên và sát trận khắc trong cơ thể, tạo thêm áp lực đối với con đường Thạch Hạo lựa chọn."},{"chuong":1246,"tieuDe":"Thiên Chuy Bách Luyện","tomTat":"Thạch Hạo bế quan suốt nửa năm không có tin tức, khiến nhiều người bên ngoài cho rằng hắn thiếu cổ chủng hoàn mỹ và đã thất bại trên con đường tu hành. Trái với những lời chế giễu ấy, hắn đang được Đại trưởng lão dùng dược dục, kịch độc, binh khí, Thần Sơn và vạn nhận rèn thân tới giới hạn để chuẩn bị cho con đường lấy thân làm chủng. Sau giai đoạn luyện thể, Thạch Hạo tu Đoán Thần Pháp, tạo được nguyên thần thứ hai rồi đốt và dung luyện nó vào chủ nguyên thần để loại bỏ tạp chất, tăng cường thần hồn. Đại trưởng lão tiếp tục truyền tàn quyết có nét tương đồng với Bình Loạn Quyết, giúp hắn hóa nguyên thần thành kiếm thai, chiến mâu và thiên đao. Khi biết Hồn khí của Dị Vực từng gây tổn thất khủng khiếp cho cửu thiên thập địa, Thạch Hạo chủ động dùng nguyên thần tay không đối kháng Xích Kim giản mười tám tiết. Qua quá trình tôi luyện này, hắn quyết tâm đưa cả thân thể lẫn nguyên thần tới cảnh giới bất diệt, bất hoại, trong khi ngoại giới vẫn chờ xem hắn thất bại."},{"chuong":1247,"tieuDe":"Phong Vân Động Cửu Thiên","tomTat":"Sau sáu tháng được Đại trưởng lão huấn luyện khắc nghiệt, Thạch Hạo đạt tới cực hạn vượt xa Thiên Thần thông thường, với thân thể đủ sức phá pháp khí Thiên Thần và nguyên thần có thể đối kháng hồn khí. Đại trưởng lão xác nhận hắn là Thiên Thần mạnh nhất mình từng gặp rồi chuẩn bị cho đệ tử bước lên con đường lấy thân làm chủng mà bản thân từng thất bại. Ông dùng Đại La Tiên Kiếm lấy tâm đầu huyết và bổ mở kỳ dị hạt giống, để Thạch Hạo tiến vào thay thế thần thai bên trong, sau đó dùng Bù thiên dược phong kín hạt giống và mang tới tạo hóa địa chôn xuống. Thạch Hạo từ đó biến mất khỏi tầm mắt thế gian suốt một năm, còn nơi nghỉ chân cũ của Đại trưởng lão tại Thiên Thần thư viện dần trở nên hoang vu. Trong thời gian ấy, Thập Quan Vương Thiên Tử xuất quan sau khi dung hợp viên mãn cây non Thế Giới thụ, gây ra hàng loạt dị tượng và dùng Long quyền làm vỡ trời. Chỉ vài ngày sau, một người khác tại Tiên viện cũng dung hợp thành công Hồng Mông Tử Khí hạt giống, khiến tử khí bao phủ ba vạn dặm và trở thành một chí tôn trẻ tuổi mới. Những biến động liên tiếp báo hiệu cuộc tranh phong của đại thời đại đã thực sự bắt đầu."},{"chuong":1248,"tieuDe":"Mùa Xuân Dưỡng Hạt Giống Chôn Dưới Đất","tomTat":"Sự xuất thế của Cây non Thế Giới thụ và Hồng Mông Tử Khí hạt giống làm các đại tộc trên chín tầng trời chấn động, báo hiệu một thế hệ chí tôn trẻ tuổi mang Vô Địch cổ chủng đang quật khởi. Trong lúc ngoại giới chờ đợi cuộc tranh phong ấy, Đại trưởng lão bí mật đưa Thạch Hạo rời Thiên Thần Thư Viện tới Thanh Vi Thiên, chôn hắn trong cổ địa tràn ngập tiên thiên thổ khí. Bên trong hạt giống kỳ dị, Thạch Hạo được quy tắc và trật tự thiên địa bao quanh, nhờ đó trực tiếp quan sát bản chất thế giới và cảm ngộ vạn đạo. Hắn quyết định không dung hợp đạo chủng ngoại giới mà xác lập con đường lấy thân làm chủng, dùng đại thiên địa để đánh thức thế giới và các Tiên môn trong chính cơ thể. Đại trưởng lão đồng thời hé lộ rằng sự lệ thuộc quá sâu vào bản nguyên bản giới từng khiến một bộ phận cường giả Cửu Thiên Thập Địa không thích ứng khi đối đầu dị vực. Ngay khi Thạch Hạo bắt đầu dò xét thiên địa bản nguyên theo con đường mới, một sức mạnh bí ẩn điều động quy tắc công kích hắn. Sau khi ổn định trong không gian nội bộ của hạt giống, hắn phát hiện thứ được thai nghén không phải Tiên kim mà là một nữ sinh linh sống. Nữ nhân tóc dài hiện hình giữa tiên quang và hỗn độn khí, mang theo khí tức nguy hiểm rồi bất ngờ mở mắt."},{"chuong":1249,"tieuDe":"Một Kỷ Nguyên Sau Gặp","tomTat":"Bên trong Thiên Địa kỳ dị hạt giống, Thạch Hạo phát hiện một nữ Tiên Thai tóc tím đang được trời đất thai nghén và vô tình làm gián đoạn quá trình thành tiên của nàng. Nữ tử ban đầu nổi sát ý, dùng pháp ấn cùng Tử Hà thể hiện sức mạnh áp đảo, trong khi hạt giống ngăn Đại trưởng lão ở ngoài biết được tình hình. Khi biết Thạch Hạo có Bổ Thiên dược từng khiến hạt giống khép lại, nàng chuyển sang thương lượng, cho hắn mượn Thiên Địa Thai Bàn tu hành với điều kiện phải tái phong bế đạo chủng sau khi thoát ra. Nữ tử sau đó vận dụng đại đạo và mảnh vỡ thời gian để suy diễn tương lai, nhìn thấy một kỷ nguyên hắc ám với máu nhuộm trời cao, thi cốt thành núi và nguy cơ cả tiên cũng vẫn lạc. Nàng quyết định trì hoãn xuất thế, để Thạch Hạo thay mình ứng kiếp và hẹn gặp lại hắn sau một kỷ nguyên nếu hắn còn sống. Thạch Hạo nhận lời rồi ngồi lên phiến đá cổ là tinh hoa của đạo chủng, lập tức được Chư Thiên vạn đạo bao phủ giữa tiếng kinh văn thần bí."},{"chuong":1250,"tieuDe":"Bên Trong Hạt Giống Ngộ Đạo","tomTat":"Thạch Hạo tiến vào trung tâm thiên địa cuống rốn bên trong hạt giống kỳ dị, nơi kinh văn và chư thiên quy tắc phô bày những trật tự căn bản nhất. Trong quá trình ngộ đạo, hắn xác lập con đường trường sinh không lệ thuộc hoàn toàn vào đại thiên địa và nhận ra thân thể chứa vô số giới tàng cùng Tiên môn chờ khai mở. Nguyên Thủy Chân Giải trên nguyên thần cộng hưởng với quy tắc, giúp hắn phân giải xích thần trật tự thành các hạt căn bản rồi thử tái tổ hợp chúng. Một lần va chạm khiến không gian sụp đổ, nhưng phiến đá trung tâm phát sáng hóa giải tai họa, trong khi nữ tử bí ẩn đứng gần đó hoảng sợ con đường thành đạo của mình bị chấm dứt. Thạch Hạo tiếp tục dùng các hạt quy tắc để dựng lại Liễu Thần pháp và những bảo thuật khác từ tầng bản chất. Vì quá chấp mê vào các hạt nhỏ bé, hắn bị cây búa màu vàng do đại đạo hóa thành đánh trọng thương, song phiến đá đã chắn phần lớn uy lực. Sau đòn cảnh tỉnh, hắn nhận ra đại thế và đạo chí cao mới là căn bản, từ đó bước vào tầng ngộ đạo sâu hơn và bắt đầu con đường lột xác, niết bàn có thể ảnh hưởng cả đời."},{"chuong":1251,"tieuDe":"Bên Trong Đạo","tomTat":"Uy thế đại đạo giáng xuống khiến sinh mệnh và linh hồn Thạch Hạo chấn động, nhưng phiến đá ở trung tâm hạt giống bảo vệ hắn khỏi bị hủy diệt. Sau thời gian dài thử ghép vô số quy tắc thành toàn cảnh đại đạo mà chỉ tạo được một phần đại thế, hắn nhận ra các pháp tắc riêng lẻ chỉ là những bộ phận của đại đạo duy nhất. Thạch Hạo vì thế chuyển hướng, xem thân thể mình là càn khôn và dẫn trật tự thần liên vào máu thịt để tìm kiếm tự thân đạo. Các quy tắc liên tục làm thân thể hắn tan vỡ, trong khi phiến đá bảo hộ và thúc đẩy quá trình phục hồi để huyết dịch, gân mạch cùng xương thịt cộng hưởng với đạo tắc. Khi hắn tiến vào trạng thái tịch diệt sâu, vô số pháp tắc bện thành Đạo chi kén quanh thân thể. Một đoàn hỏa từ trong kén lao ra, hóa thành gương soi đạo tắc rồi biến thành tiên hỏa mang hỗn độn khí, nung chiếc kén đến cháy đen và phá diệt. Nữ nhân quan sát trong hạt giống ban đầu nghi Thạch Hạo tẩu hỏa nhập ma, nhưng khi thấy phần thân thể lộ ra chưa bị thiêu nát, nàng bắt đầu tin rằng hắn có thể hoàn tất lần lột xác này."},{"chuong":1252,"tieuDe":"Chủng Thành","tomTat":"Đạo kén quanh Thạch Hạo dần vỡ vụn rồi bất ngờ bùng cháy, khiến chư thiên quy tắc hóa thành đạo hỏa thiêu hắn đến sát bờ hình thần câu diệt. Trong tuyệt cảnh, hắn vẫn quan sát phù văn và bản nguyên đại vũ trụ, dùng kinh nghiệm rèn luyện tiên khí để đánh thức sức mạnh trong cơ thể. Nhiều cánh cửa trong thân thể hé mở, phát ra thanh quang của Nội Đạo để đối kháng đại đạo bên ngoài; hai phía còn tự nhiên kết hợp thành Âm Dương Thái Cực Đồ, khiến thời không tạm thời ngưng đọng. Thạch Hạo phủ nhận đạo đồ này là điểm cuối và xác định con đường của mình chỉ dựa vào thân thể cùng tinh thần bản thân. Khi các cánh cửa khép lại, thanh quang đan xen thành một hạt giống dung hợp với cơ thể, giúp hắn hoàn thành bước khởi đầu của con đường lấy thân làm chủng. Đoàn hỏa thần bí sau đó lên tiếng rằng hắn chưa đủ trưởng thành để duy trì trạng thái mở môn, đồng thời để lộ dị tượng vô số sinh linh chiến đấu, kêu rên và hồn ảnh xung kích trong hỏa quang."},{"chuong":1253,"tieuDe":"Lừa Gạt Thiên","tomTat":"Thạch Hạo đã khiến thanh quang từ những cánh cửa trong cơ thể hội tụ thành đạo chủng, bước đầu khai thông con đường lấy thân làm chủng chưa từng có. Trong quá trình dùng nội đạo tái cấu trúc bảo thuật Liễu Thần, hắn lĩnh ngộ bản chất của sinh mệnh, niết bàn và sự hồi sinh sau vô số lần hủy diệt. Thiên địa lập tức giáng xuống tuyệt sát vượt xa Giáo Chủ cảnh, đánh thân thể hắn tan thành tro bụi, nhưng đạo chủng đã che giấu tinh huyết và Nguyên Thần, giúp hắn lừa qua thiên uy rồi tái sinh. Rời thiên địa cuống rốn, hắn báo tin thành công cho Đại trưởng lão, khiến ông xúc động vì tuyệt lộ từng chôn vùi vô số tiên hiền cuối cùng đã được khai thông. Thạch Hạo dùng Bổ Thiên Dược khép lại hạt giống kỳ dị chứa cô gái, thu nó đi để sau này chôn tại một nơi bí mật đúng như lời hứa. Trong lúc thăm dò sâu hơn hỏa động, Đại trưởng lão đào được một sinh linh hình người cháy đen có đôi cánh vàng vẫn còn sống, chỉ khẽ rung cánh đã khiến cả cổ động rung chuyển và nóng chảy. Theo lệnh Đại trưởng lão, Thạch Hạo giữ kín bí mật rồi trở về Thiên Thần Thư Viện, lúc này mới biết ngoại giới đã trôi qua hai năm rưỡi và nhiều thiên kiêu đã dung hợp hoàn mỹ hạt giống, gây chấn động khắp Cửu Thiên Thập Địa."},{"chuong":1254,"tieuDe":"Nhất Khí Hóa Vạn Linh","tomTat":"Lam tiên đồng thời phát động chín đại thần thông, tạo dư âm đủ làm những người quan chiến bị thương, nhưng Thạch Hạo dùng tinh hà cốt văn ngăn chặn rồi diễn hóa thành vô số vạn linh để nghiền nát thế công. Uy lực của Nhất Khí Hóa Vạn Linh khiến chính hắn bất ngờ, song bí thuật cũng hút lượng lớn tinh khí thần, buộc hắn thu vạn linh trở lại cơ thể. Đại tu đà chớp thời cơ tụng Phật Đà tâm kinh trấn áp tinh thần, nhưng Thạch Hạo ổn định nhờ tiềm lực từ những cánh cửa trong cơ thể và dùng Bình Loạn quyết với kiếm thai Nguyên Thần giả thật khó lường để phản kích. Tử Nhật Thiên Quân ngừng ngưng tụ Hồng Mông tử khí và nhập chiến, sau đó bị Lôi Đế ấn chấn đến ho ra máu. Thạch Hạo tiếp tục lấy thân thể đối đầu Trượng Sáu Kim Thân của Đại tu đà, truy kích Lam tiên đến rách hai tay áo và bị thương cánh tay. Hắn còn dùng một phần Nguyên Thần trêu chọc Đại tu đà, rồi thi triển Bảo thuật Liễu Thần suýt khóa cổ Tử Nhật Thiên Quân. Cuối cùng, Thạch Hạo vẫn tung hoành giữa vòng vây của ba Chí Tôn trẻ tuổi mà không rơi xuống hạ phong."},{"chuong":1255,"tieuDe":"Thân Tức Là Chủng","tomTat":"Thạch Hạo tiếp tục một mình giao chiến với Tử Nhật Thiên Quân, Đại Tu Đà và Lam Tiên, khiến Tử Nhật Thiên Quân phải liều mạng kích hoạt sức mạnh của Hồng Mông Tử Khí chủng. Hạt giống tím câu thông quy tắc từ vực ngoại, bộc phát uy thế làm hư không tan vỡ và các núi thần trong Thiên Thần thư viện rạn nứt, buộc trưởng lão cùng hộ giáo trận pháp phải ổn định khu vực. Trước sức ép ấy, những môn thần bí trong cơ thể Thạch Hạo mở rộng khe hở, giải phóng tiềm năng bản nguyên để hắn lấy chính thân thể làm đại đạo hạt giống. Nắm đấm của hắn xuyên thủng hình thể Hồng Mông Tử Khí chủng, phá tan thế công của đối thủ và khiến những người quan chiến nhận ra hắn có thể đã đi thông con đường lấy thân làm chủng. Thạch Hạo sau đó đánh Tử Nhật Thiên Quân đến ho ra máu, cánh tay biến dạng và thân thể gần tan vỡ. Đại Tu Đà cùng Lam Tiên quay lại can thiệp, nhưng Thạch Hạo vẫn giữ thế quyền áp đảo và tuyên bố sẽ giết bất kỳ ai cản đường."},{"chuong":1256,"tieuDe":"Bất Bại Truyền Kỳ","tomTat":"Sức chiến đấu Cực Đạo của Thạch Hạo khiến các trưởng lão kết luận hắn đã đi thông con đường lấy thân làm chủng, kỳ tích mà những thiên kiêu từ thời Tiên Cổ đều không thể hoàn thành. Hắn áp đảo Tử Nhật Thiên Quân, đánh gãy nhiều xương và xuyên thủng ngực bụng đối thủ, buộc Đại Tu Đà cùng Lam Tiên phải toàn lực liên thủ cứu đồng môn. Dù Tử Nhật cố triệu hồi hoàn chỉnh Hồng Mông Tử Khí chủng, Thạch Hạo vẫn đánh thân thể hắn rách nát; đạo chủng phải hiện ra bảo hộ, còn trưởng lão Tiên Viện dùng Kim đan cứu mạng. Chiến tích lấy một địch ba và trọng thương một đời Thiên Quân giúp Hoang tái lập uy danh bất bại, khiến Vương Hi lo ngại cho Vương gia còn Yêu Nguyệt nảy ý chiêu mộ hắn. Giữa lúc Thạch Hạo ép Lam Tiên vào thế bị động, nhiều Chí tôn trẻ tuổi mới đến phá vỡ ao bùn, làm lộ Tiên phủ cùng thế giới dưới lòng đất. Thạch Hạo không lao xuống một mình mà gọi Tào Vũ Sinh, Ma Nữ và đệ tử Thiên Thần thư viện, quyết định che chở cả nhóm cùng tiến vào."},{"chuong":1257,"tieuDe":"Dưới Lòng Đất","tomTat":"Thạch Hạo triệu tập Tào Vũ Sinh, Thái Âm Ngọc Thỏ, Trường Cung Diễn, Ma Nữ, Phượng Vũ và các đệ tử Thiên Thần Thư Viện cùng xuống ao bùn, tiến vào thế giới Tiên phủ dưới lòng đất. Khi một kẻ ẩn trong bóng tối dùng lôi đình tập kích, hắn bắt trọn đòn đánh trong bàn tay rồi dội hàng vạn đạo lôi điện xuống, kích hoạt cổ trận và buộc những người đến trước phải vất vả phòng ngự. Sau đó, Thạch Hạo dùng man lực phá hộp đá lấy từ ao bùn, phát hiện Bát Trân Quy đã thông linh và biết nó từng bị một nguồn sức mạnh bí ẩn cuốn xuống đây rồi trấn áp. Hắn tạm giữ sinh linh quý hiếm này để bổ sung huyết khí. Địa tầng tiếp tục sụp vỡ, để lộ một Tiên Thành thanh kim khổng lồ với chín ngọn núi đá cùng các cổ động phủ dâng tiên khí. Cổng thành vốn được phù văn nguy hiểm bảo vệ bỗng tự mở, còn toàn bộ phù văn trên tường thành biến mất. Cuối cùng, vài sinh linh hình người bọc kín trong giáp trụ, mang theo tiên khí chậm rãi bước ra, khiến mọi người kinh ngạc nghi ngờ đó là những Chân Tiên còn sống."},{"chuong":1258,"tieuDe":"Tiên Thành","tomTat":"Đoàn thiên kiêu tới Tiên Thành, nơi những sinh linh mặc giáp đen mang tiên khí và sử dụng trang bị pha Hắc Ám Tiên Kim canh giữ cửa vào. Người thủ thành dùng mắt dọc kiểm tra huyết mạch, xác nhận Kỳ Lân ấu thú có quan hệ với chư Tiên thời Tiên cổ và nhờ lời cầu xin của nó mà cho cả đoàn tiến vào. Mạc Đạo bị giữ lại vì từng sống tại dị vực, nhưng sau khi kiểm tra vẫn được vào thành với phạm vi hoạt động bị hạn chế. Các nhân vật lớn tuổi của Thiên Thần Thư Viện, Tiên Viện và Thánh Viện bị từ chối vì cơ duyên trong thành chỉ dành cho thế hệ trẻ mang huyết thống Tiên cổ tinh thuần, đồng thời nguồn gốc tòa thành do hai vị Tiên Vương lưu lại được hé lộ. Thạch Hạo đi cuối đội ngũ để đề phòng Lam Tiên cùng các chí tôn trẻ tuổi, khiến họ kiêng dè chưa muốn giao chiến. Bên trong thành, mọi người phát hiện một hồ nước có ba cây Dẫn Hồn Liên, dược tính trong nước có thể bồi bổ nguyên thần nên Tào Vũ Sinh cùng nhiều người lập tức xuống hấp thu. Tào Vũ Sinh sau đó trêu chọc một sinh vật nhỏ tự nhận hồ là nơi tắm của mình và bị nó đánh bay đến bất tỉnh chỉ bằng một quyền."},{"chuong":1259,"tieuDe":"Lực Chi Cực Điểm","tomTat":"Tào Vũ Sinh bị một con kiến kim sắc dài khoảng một tấc dùng một quyền đánh bất tỉnh và văng xa hàng chục dặm. Thạch Hạo nhận ra sinh linh nhỏ bé này là Thiên Giác Nghĩ, giống loài đứng đầu Thái Cổ Thập Hung về sức mạnh thân thể, đồng thời khao khát bảo thuật lực cực điểm rất phù hợp với con đường của mình. Hắn nhớ lại Trích Tiên từng tiến vào một sào huyệt Thiên Giác Nghĩ tại Tiên Cổ di địa và nghi đối phương đã tu thành bảo thuật của tộc này, thậm chí còn nắm giữ một chiếc cổ giác thần bí. Các thủ thành xác nhận Thiên Giác Nghĩ nhỏ là hậu duệ được họ cứu sống từ thời Tiên Cổ, ngủ say hàng tỉ năm rồi mới hoàn chỉnh ấp nở trong thời đại hiện tại. Họ cũng tiết lộ bản thân chỉ là những ý chí lão binh còn sót lại trong thân thể đã được chế thành con rối để tiếp tục bảo vệ hỏa chủng và truyền thừa. Ban đầu truyền thừa hạch tâm chỉ được dành cho Thiên Giác Nghĩ nhỏ và Kỳ Lân trắng, nhưng Lam Tiên thuyết phục các lão binh trao cho người đương đại một cơ hội. Điều kiện được đưa ra là phải nâng được Nguyên Mẫu Đỉnh, trọng khí đứng đầu thời Tiên Cổ, khiến một chí tôn trẻ tuổi lập tức bước ra thử sức còn các đệ tử Thiên Thần Thư Viện kỳ vọng Thạch Hạo tham gia."},{"chuong":1260,"tieuDe":"Lực Bạt Nguyên Mẫu Đỉnh","tomTat":"Lữ Hồng của Lữ gia vừa xuất quan và trở thành người đầu tiên thử nâng Nguyên Mẫu Đỉnh, nhưng cả sức mạnh thân thể lẫn tuyệt thế bảo thuật đều không thể lay chuyển nó. Các lão binh giải thích đại đỉnh trên núi chỉ là hình chiếu của Tiên khí chân chính, mang trọng lượng tương ứng sức nâng của Thiên Giác Nghĩ thời trẻ và chỉ chấp nhận sức mạnh thân thể thực sự. Tử Nhật Thiên Quân vận dụng Hồng Mông Tử Khí chủng nhưng bị phản phệ đến ho ra máu, còn Lam Tiên và Tào Vũ Sinh cũng lần lượt thất bại. Đại Tu Đà cùng Thích Cố khiến đại đỉnh rung vang nhưng vẫn không thể nâng nó khỏi mặt đất. Thạch Hạo sau đó vận dụng sức mạnh thân thể Cực Đạo, tạo trường vực ảnh hưởng không gian và thời gian rồi thành công nhấc hình chiếu Nguyên Mẫu Đỉnh. Thành tích này khiến một lão binh nghi hắn đã đi thông một con đường đặc biệt của kỷ nguyên hiện tại, đồng thời làm Thiên Giác Nghĩ nhỏ kinh ngạc vì binh khí của mình lại được người khác nâng lên trước."},{"chuong":1261,"tieuDe":"Bất Diệt Kinh","tomTat":"Thạch Hạo nâng được hình chiếu cổ đỉnh mà nhiều chí tôn trẻ tuổi không thể lay chuyển, khiến cả tiên sơn rung động và hoàn thành khảo nghiệm sức mạnh thân thể. Trước sự kinh ngạc của các lão binh, hắn xác nhận mình đã thành công lấy thân làm chủng, còn Tào Vũ Sinh công khai chỉ trích Tiên viện vì từng không trao bảo chủng cho hắn. Thủ lĩnh lão binh đánh giá nếu chuyên tâm luyện thể, Thạch Hạo có thể sánh ngang Thiên Giác Nghĩ. Khi Thạch Hạo thuật lại Chuy Cốt Pháp do Đại trưởng lão truyền, người này nhận ra đó chỉ là một nhánh nông cạn thoát thai từ Bất Diệt Kinh. Các lão binh tiếp đó hé lộ Bất Diệt Kinh là vô thượng bảo điển luyện thể thời Tiên cổ, được đồn có thể khiến thân thể bất hủ và tái sinh thần phách sau khi nguyên thần bị diệt. Tuy chân kinh đã thất lạc, tung tích của nó được thu hẹp vào ba khả năng: còn ẩn trong Tiên thành, rơi lại tại chiến trường năm xưa của Thiên Giác Nghĩ hoặc nằm trong một vùng cấm thuộc Cửu Thiên Thập Địa. Thạch Hạo nhận ra mình rất cần truyền thừa này, còn hậu duệ Thiên Giác Nghĩ tin rằng chân kinh chưa biến mất và quyết tâm học nó trong tương lai."},{"chuong":1262,"tieuDe":"Nơi Tạo Hóa","tomTat":"Sau khi vượt qua khảo nghiệm, Thạch Hạo được thủ lĩnh cổ thành cho phép một mình tiến vào động phủ Thiên Giác Nghĩ tìm Bất Diệt kinh. Trước khi lên đường, hắn quay lại hồ gần cửa thành và chống lại Đại Tu Đà, Lam Tiên cùng nhiều chí tôn trẻ tuổi để hái đủ ba cây Dẫn Hồn liên. Duy nhất động thiên, cốt văn Nguyên Thủy Chân Giải và thanh quang từ các cánh cửa trong cơ thể giúp hắn hóa giải cuộc hợp kích rồi mang thần dược rời đi. Thạch Hạo giữ một cây dự phòng, chia hai cây cho nhóm Trường Cung Diễn và Tào Vũ Sinh, sau đó cùng Thiên Giác Nghĩ nhỏ tiến vào động phủ. Hai người tìm kiếm suốt một ngày một đêm trong mê cung hang động nhưng vẫn chưa thấy Bất Diệt kinh. Thiên Giác Nghĩ nhỏ cuối cùng dùng chiếc sừng vàng mở một cánh cửa bí mật trong vách đá. Phía sau cửa là máu, vảy, lông chim và các phần di hài mang uy thế khủng khiếp, khiến Thạch Hạo nghi ngờ nơi đây chính là tuyệt địa nơi Thiên Giác Nghĩ đời trước cùng nhiều cường địch đồng quy vu tận."},{"chuong":1263,"tieuDe":"Thiên Giác Nghĩ","tomTat":"Thạch Hạo chịu uy áp khủng khiếp trên chiến trường và biết đầu lâu vàng khổng lồ chỉ là lớp xác Thiên Giác Nghĩ từng lột bỏ. Tiểu Thiên Giác Nghĩ kể rằng cha mình đã chống lại nhiều cường giả Dị vực, mang trọng thương kéo dài đến đầu kỷ nguyên hiện tại rồi hao hết tinh nguyên để cứu nó sau khi mẹ cùng các anh chị em đều chết trận. Hai người tìm kiếm Bất Diệt Kinh nhưng không thu được manh mối, còn Thạch Hạo chỉ lấy được một chiếc lông chim màu xám để chuẩn bị luyện Ngũ Cầm Phiến. Trước nguy cơ Dị vực tiếp tục kéo tới, Thạch Hạo đề nghị Tiểu Thiên Giác Nghĩ cưỡng ép kích phát huyết mạch và để một tia Nguyên Thần bám vào Vạn Linh Đồ quan sát. Tiểu Thiên Giác Nghĩ hóa thành thân thể lớn như núi, bộc phát sức mạnh đủ đối đầu những chí tôn trẻ tuổi hàng đầu và khiến lớp lột xác của cha thức tỉnh. Sóng vàng từ lớp lột xác phá vỡ nhiều di vật Tiên đạo chung quanh, buộc Vạn Linh Đồ phát sáng bảo vệ Nguyên Thần Thạch Hạo. Cuối cùng, hình người tóc vàng của Thiên Giác Nghĩ hiện ra và tuyên bố đã từng gặp Thạch Hạo từ hàng tỉ năm trước."},{"chuong":1264,"tieuDe":"Tương Lai Đen Tối","tomTat":"Thạch Hạo suy ra Thiên Giác Nghĩ từng nhìn thấy mình trong một góc tương lai thông qua dòng sông thời gian. Trong lúc Tiểu Thiên Giác Nghĩ mất ý chí và không nhận ra khắc dấu của cha, tàn hồn Thiên Giác Nghĩ truyền cho Thạch Hạo ký ức về trận chiến cuối Tiên Cổ, nơi ông bị ba tuyệt thế cao thủ cùng đông đảo sinh linh bất hủ vây đánh đến vẫn lạc. Ba đại địch gồm chủ nhân thanh kiếm xanh, đầu sỏ từng vượt dòng thời gian và chủ nhân trường thương vàng đều được xác nhận vẫn còn sống. Thiên Giác Nghĩ cảnh báo một thời đại đen tối hơn Tiên Cổ sẽ tới, chiến trường thật sự vượt xa cửu thiên thập địa và một khả năng tương lai cho thấy Thạch Hạo phải chiến đấu cô độc đến tuổi già. Thạch Hạo không chấp nhận kết cục ấy, khẳng định sẽ dùng đôi quyền mở ra một tương lai khác. Thiên Giác Nghĩ còn nhắc đến bí mật kim huyết của nhất mạch người thủ hộ và những người có cùng nguồn gốc với họ. Cuối cùng, theo lời thỉnh cầu của Thạch Hạo, ông truyền khắc dấu chỉ đường tới nơi lưu giữ Bất Diệt kinh, mong hắn mang toàn bộ cổ kinh ra ngoài."},{"chuong":1265,"tieuDe":"Cơ Duyên Tận","tomTat":"Tàn niệm Thiên Giác Nghĩ giải thích rằng Bất Diệt Kinh có thể khiến thân thể bất hoại và trở thành nơi tái dựng linh thức, nhưng ông nghi ngờ bản kinh đang lưu truyền có sai lầm nên không trực tiếp truyền lại. Sau khi từ chối gặp con trai vì muốn nó tự lập, tàn niệm của ông hóa thành kim quang nhập vào lớp lột xác đầu lâu. Thạch Hạo đánh thức Tiểu Thiên Giác Nghĩ đang phát cuồng, dùng Vạn Linh Đồ dẫn nó ra khỏi động phủ rồi lấy chân thân thi triển Côn Bằng pháp trấn áp. Khi tỉnh táo, Tiểu Thiên Giác Nghĩ đồng ý theo hắn rời đi tìm Bất Diệt Kinh hoàn chỉnh. Bên ngoài, Thạch Hạo công khai thách thức những chí tôn trẻ tuổi đang dò xét, khiến Đại Tu Đà và Lam Tiên lựa chọn nhượng bộ. Đoàn người sau đó đến thần hồ, phát hiện vũng bùn hình thành từ vườn Trường Sinh dược mục nát và tranh thủ dùng nó để thoát thai hoán cốt. Tiểu Kỳ Lân trắng là sinh linh duy nhất được vào nơi sâu nhất của tòa núi thứ hai nhận truyền thừa dành cho hậu đại Kỳ Lân. Cuối cùng, Thạch Hạo nhờ lão binh chăm nom người của Thiên Thần Thư Viện rồi mang Tiểu Thiên Giác Nghĩ lên đường tới nơi nguy hiểm cất giữ Bất Diệt Kinh hoàn chỉnh."},{"chuong":1266,"tieuDe":"Tranh Cướp","tomTat":"Thạch Hạo đưa Thiên Giác Nghĩ rời động phủ dưới lòng đất, khiến các tu sĩ và trưởng lão ba thư viện nhận ra một hậu duệ thuần huyết của Thập Hung vẫn còn sống. Giá trị của bảo thuật và lực cực điểm huyết lập tức khiến Tiên Viện, Thánh Viện cùng nhiều Trường Sinh thế gia nảy sinh ý định tranh giành. Lão già ba mắt của Tiên Viện và bà lão tóc tím của Thánh Viện lần lượt lôi kéo Thạch Hạo, nhưng hắn kiên quyết từ chối cả hai để tiếp tục con đường riêng. Người Vương gia, Nguyên Thanh và lão giả Phong tộc sau đó yêu cầu giữ Thiên Giác Nghĩ lại dưới danh nghĩa bảo vệ, trong khi Nhị Trưởng Lão khẳng định quyền quyết định thuộc về Thạch Hạo và Thiên Giác Nghĩ. Đúng lúc tranh chấp căng thẳng, Đại trưởng lão trở về sau gần ba năm và công khai quát đuổi mọi thế lực dám can thiệp vào Thiên Thần Thư Viện. Sự xuất hiện của ông lập tức đảo chiều cục diện, khiến phụ thân Yêu Nguyệt cùng nhiều người khác chuyển sang ủng hộ việc để Thiên Giác Nghĩ ở lại thư viện."},{"chuong":1267,"tieuDe":"Đối Chọi Gay Gắt","tomTat":"Đại trưởng lão trở về Thiên Thần Thư Viện, dùng uy thế vô hình khiến Vương gia cùng các thế lực đang nhòm ngó Thiên Giác Nghĩ phải lập tức thu liễm. Trong lúc các Trường Sinh thế gia tụ hội vì phủ đệ Tiên Vương dưới lòng đất, nguyên lão Phong tộc tới chào hỏi, còn Từ Minh Hiên công khai khen Thạch Hạo và giao hảo với Đại trưởng lão. Hoàng chủ Từ gia sau đó tuyên bố muốn tìm một tài tuấn trẻ tuổi làm đạo lữ cho Yêu Nguyệt rồi nhìn về phía Thạch Hạo, khiến mọi người suy đoán Hoang đang được chọn làm con rể. Vương gia lo sợ viễn cảnh Thạch Hạo liên minh với Từ gia, bởi họ từng ép hắn đào quáng, đeo Kim Cương Trác và định đưa hắn vào Thái Sơ Cổ Quáng. Vương Mãng Long dùng chính quá khứ ấy để châm chọc Thạch Hạo cùng Từ gia, khiến Thạch Hạo tung toàn lực đánh tới và tuyên bố có thể giết sạch mười thiên tài đứng đầu Vương gia. Từ Minh Hiên chặn Thạch Hạo, tự mình tát Vương Mãng Long trọng thương rồi quy lời nói của hắn thành nguy cơ khơi mào cuộc chiến kéo dài vạn năm giữa hai tộc. Trưởng lão Vương gia dù phẫn nộ vẫn phải hừ lạnh và rút lui, không dám tiếp tục truy cứu."},{"chuong":1268,"tieuDe":"Một Đường Hướng Bắc","tomTat":"Từ Minh Hiên công nhận Thạch Hạo không sai và công khai cảnh cáo người Vương gia không được dùng lời lẽ bôi nhọ con gái mình. Sau khi trở về khiến những kẻ nhòm ngó động phủ Tiên Vương dưới lòng đất không dám manh động, Đại trưởng lão bí mật gặp Thạch Hạo, phong tỏa cuộc nói chuyện và nghiêm cấm hắn tiết lộ sinh linh cổ xưa được đào lên dưới đống hài cốt. Ông trao cho Thạch Hạo một chiếc nhẫn xanh đen bí ẩn, dặn phải đeo trên tay vì tương lai có thể cần dùng. Muốn nhanh chóng mạnh lên trước nguy cơ tại Biên Hoang, Thạch Hạo cùng Tiểu Thiên Giác Nghĩ mất bảy ngày đi qua nhiều truyền tống trận để tới cực bắc Vô Lượng Thiên và hướng đến Bắc Hải bãi đá tìm Bất Diệt Kinh. Hai người lên một minh thuyền cổ bằng xương có khả năng tự tiến vào vùng biển phủ sương đen. Thạch Hạo nhận ra hình dáng con thuyền giống hệt những thuyền giấy từng thấy gần Côn Bằng sào, rồi phát hiện vách thuyền bất ngờ rỉ máu đen đỏ. Dị biến khiến hắn nảy sinh suy đoán rằng chân thân cô gái gấp thuyền giấy có thể đang ở trong Bắc Hải."},{"chuong":1269,"tieuDe":"U Minh","tomTat":"Thạch Hạo và Thiên Giác Nghĩ nhỏ lênh đênh trên vùng biển đen tuyệt đối tĩnh lặng, rồi phát hiện Minh Thuyền bằng xương bất ngờ rỉ máu và có dấu hiệu lệch khỏi tuyến đường tới Bắc Hải Thạch Lâm. Thiên Giác Nghĩ nhỏ lấy máu cho vào đồng đỉnh, dùng Đại Lực Tiên Diễm luyện hóa và để lộ một giọt bảo huyết lưu giữ dấu ấn về sinh linh đáng sợ từng bị trường thương vàng đâm xuyên, với máu bắn ra đủ sức phá hủy nhiều ngôi sao. Sau ba ngày, con thuyền tiến vào màn sương dày cùng hải vực chất đầy hài cốt khổng lồ, khiến Thạch Hạo nghĩ tới đại kiếp, cuộc xâm lấn của dị vực và số phận của thế hệ mình. Hắn cũng nhớ lại Bạch y nữ Đế từng nghịch dòng thời gian giúp mình tại chiến trường Tiên gia, trong khi một cự đầu từ muôn đời trước từng vượt thời gian tới chặn giết hắn. Minh Thuyền sau đó rời biển chết, đi vào thế giới đảo ngược có mặt trời luyện từ xác Kim Ô nằm sát mặt nước, còn núi rừng và sinh linh hiện diện trên bầu trời. Cuối cùng, Thiên Địa mắt chứa vô số mảnh vỡ thời gian xuất hiện, dùng tiếng sấm công kích nguyên thần rồi kéo cả Thạch Hạo lẫn Thiên Giác Nghĩ nhỏ vào vòng xoáy. Theo thủ trát của Thiên Giác Nghĩ đời trước, người không đủ sức áp chế đương đại có thể chết già giữa đường hoặc biến mất trong Luân Hồi."},{"chuong":1270,"tieuDe":"Thời Gian Đường Nối","tomTat":"Thạch Hạo và Thiên Giác Nghĩ nhỏ bị một trường vực vô hình khống chế giữa hải vực sấm sét rồi kéo cả minh thuyền về phía đường nối thời gian. Thạch Hạo dùng Bảo thuật Liễu Thần và Luân Hồi bảo thuật để phá cầm cố, còn Thiên Giác Nghĩ nhỏ vận dụng sức mạnh cực điểm, nhưng mọi cách đều thất bại và Luân Hồi bảo thuật còn khiến lực hút tăng mạnh. Thạch Hạo lần lượt lấy Lôi Đế giáp trụ, Vạn Linh Đồ, Đại La kiếm thai và tấm vảy mang long uy ra dò xét, song không món nào được xác nhận là nguồn kích hoạt dị biến. Minh thuyền xuyên qua màn sáng và rơi vào quang đạo khi lôi đình tách sang hai phía, giúp hai người tạm thời không bị đánh trúng. Sức mạnh năm tháng khiến họ có cảm giác già đi hàng vạn năm trước khi một luồng ánh sáng vĩnh hằng đảo ngược quá trình và làm thân thể trẻ lại. Trong đường nối, Thạch Hạo nhìn thấy nhiều thuyền giấy nhuốm máu mang hàng chữ quen thuộc, rồi một nữ nhân phong hoa tuyệt đại xuất hiện sau tia sét kinh thế và tiến lại gần."},{"chuong":1271,"tieuDe":"Một Bước Một Kỷ Nguyên","tomTat":"Một nữ tử áo trắng mang uy thế vô địch tiến lại gần Thạch Hạo và Thiên Giác Nghĩ nhỏ trong đường nối thời gian, khiến con kiến nhỏ run rẩy và cả hai nghe thấy tiếng chúng sinh tế tự nàng như một vị nữ Đế. Sự hiện diện của nàng làm những dị tượng sát phạt hiện ra, đồng thời đường nối trở nên bất ổn và lực lượng năm tháng đe dọa xóa bỏ Thạch Hạo cùng con kiến nhỏ. Bạch y nữ Đế thi triển Phi Tiên ánh sáng, còn những thuyền giấy đen nhuốm máu trấn áp thời gian và hư không, qua đó cứu hai người. Nhờ thủ đoạn ấy, Thạch Hạo nhận ra nàng chính là người từng cứu mình tại Tiên gia chiến trường, rồi chú ý đến pháp khí biến hóa thành mặt nạ đồng xanh che dung mạo nàng. Một giọt máu bí ẩn trong cơ thể Thạch Hạo hiện ra, hé lộ đây là vật dẫn khiến hắn và Thiên Giác Nghĩ nhỏ rơi vào đường nối thời gian. Bạch y nữ Đế xác nhận nàng đã tìm đúng người và đúng địa điểm nhưng gặp sai thời gian, bởi Thạch Hạo hiện tại vẫn chưa phải người nàng cần gặp. Nàng cảnh báo khoảng cách tưởng như chỉ một bước giữa hai người thực chất có thể kéo dài cả một kỷ nguyên và mọi cố gắng cưỡng ép vượt qua đều có nguy cơ bị thời gian xóa sạch."},{"chuong":1272,"tieuDe":"Lãng Quên","tomTat":"Thạch Hạo thử tiến về phía Bạch y nữ Đế trên đường nối thời gian nhưng suýt bị năm tháng bào mòn đến tan rã, may nhờ một con thuyền giấy xuất hiện và tỏa sáng bảo vệ. Nhận ra hai người cách nhau cả một kỷ nguyên, hắn suy ngẫm về những cuộc chiến vượt thời đại và quyết tâm trở nên mạnh hơn để nghịch chuyển viễn cảnh người thân, bằng hữu cùng cố nhân đều chôn vùi. Trong lúc đường nối mất ổn định, nữ Đế truyền đạt một thông tin chưa rõ; mặt nạ đồng xanh của nàng nứt đôi, phát ra tiên quang chạm tới hắn, còn nàng lùi lại và để rơi một giọt máu. Quy tắc vô hình sau đó xóa mất nội dung vừa được truyền cùng hình bóng nữ Đế khỏi ký ức của Thạch Hạo, khiến hắn và Thiên Giác Nghĩ nhỏ chỉ nhớ được những mảnh rời rạc về người, địa điểm và thời gian. Thạch Hạo ghi nhớ ngày mất ký ức, quyết chờ đến khi đủ mạnh sẽ hoàn nguyên chân tướng và xác định bản chất đạo tiên quang. Minh thuyền bằng xương tiếp tục đưa hai người vượt biển chết đầy khói đen, tử khí và hài cốt khổng lồ để tới Bắc Hải bãi đá. Tại vùng đá rộng lớn có nhiều cự thành và siêu tuyệt phong lưu dấu đại đạo, họ nhìn thấy ngọn núi sấm sét cùng ngọn núi đặt thi thể cổ Kim ô. Thiên Giác Nghĩ nhỏ cuối cùng hỏi liệu Bất Diệt Kinh có nằm tại nơi này hay không."},{"chuong":1273,"tieuDe":"Siêu Tuyệt Phong","tomTat":"Thiên Giác Nghĩ nhớ lại di ngôn của phụ thân về Bất Diệt kinh hoàn chỉnh và lập chí vượt qua cha, trở thành Thiên Giác Nghĩ mạnh nhất lịch sử. Tại Bắc Hải thạch lâm, Thạch Hạo chọn Kim Ô phong, đối đầu thiên hỏa cùng pháp trận cổ rồi nghịch dòng thác lửa để lên đỉnh tòa núi đã năm vạn năm không ai chinh phục. Trên đỉnh núi, hắn nghe ấn ký của Kim Ô tuyệt thế chí tôn giảng giải kinh nghiệm và diệu dụng của các cảnh giới, nhờ đó đạo hạnh tăng lên rõ rệt chỉ sau nửa canh giờ. Đám đông nhận ra hắn là Hoang và chấn động khi biết Tử Nhật Thiên Quân từng thua dưới tay hắn. Trong một ngày, Thạch Hạo liên tiếp chinh phục chín tòa Siêu Tuyệt phong, phá kỷ lục và thu hút đông đảo tu sĩ từ các thành lớn kéo tới. Khi hiệu quả nghe kinh dần suy giảm, hắn biết thêm về những Siêu Tuyệt phong hơn trăm vạn năm chưa ai đặt chân và suy đoán manh mối Bất Diệt kinh nằm tại đó. Một lão giả bản địa sau cùng tiết lộ về nơi thí luyện chung cực thuộc vùng cấm, khiến Thạch Hạo lập tức yêu cầu được chỉ đường."},{"chuong":1274,"tieuDe":"Không Người Đăng Lâm","tomTat":"Thạch Hạo tiến sâu vào Bắc Hải bãi đá để tìm manh mối Bất Diệt Kinh, lần lượt bỏ qua Siêu Tuyệt Phong và nhóm thần phong tám mươi vạn năm nhằm tiết kiệm thời gian. Tại nơi sâu nhất, hắn gặp sáu cổ sơn hơn trăm vạn năm hiếm người đăng lâm, nơi lưu lại thi thể, quan tài cùng nhiều dấu vết khiến người đời suy đoán về sinh linh mượn cái chết để thành tiên. Thành chủ và cư dân địa phương cho biết chưa ai thực sự tiến vào nơi thí luyện cuối cùng, đồng thời cảnh báo người thất bại có thể vĩnh viễn không trở ra. Thạch Hạo vẫn bước lên đường mòn, dùng một quyền phá trường vực vô hình chắn lối và khiến cả sáu cổ sơn đồng loạt rung chuyển. Khi uy áp trên đường muốn xé rách thân thể, hắn mở cửa trong cơ thể để phóng thích sức mạnh chống đỡ. Cuối cùng, qua thiên nhãn, hắn thấy một quan tài cổ bật nắp, da người rơi xuống và một sinh linh hình người trên vách núi mở mắt nhìn thẳng vào mình."},{"chuong":1275,"tieuDe":"Khủng Bố","tomTat":"Trên Siêu Tuyệt Phong, Thạch Hạo và Thiên Giác Nghĩ nhỏ phát hiện một sinh linh cổ vẫn mở mắt ngồi xếp bằng trên đoạn nhai. Một quan tài treo trên vách đá bất ngờ mở ra, để tấm da người phồng lên, phát tiếng rít rồi lao xuống khiến đoàn tu sĩ hoảng loạn. Thạch Hạo dùng thần thông Lôi Đế tung chớp giật quyền đánh trúng mục tiêu, nhưng không thể làm tấm da bị tổn hại. Một bàn tay phủ lông đỏ sau đó nâng tấm da trở lại quan tài, đóng nắp, còn sinh vật ẩn sau núi đá quỳ lạy trước quan tài. Bất chấp lời cảnh báo và cảm giác bất an, Thạch Hạo vẫn quyết định đi tiếp, Thiên Giác Nghĩ nhỏ cũng theo cùng. Hai người chịu áp lực khủng khiếp trên đường mòn và tiến tới cuối đường, chỉ còn cách chỗ ngoặt dẫn vào nơi thí luyện chung cực vài chục bước."},{"chuong":1276,"tieuDe":"Chung Cực Nơi Tập Luyện","tomTat":"Thạch Hạo cùng Thiên Giác Nghĩ vượt đoạn đường cuối dẫn vào nơi thí luyện chung cực, đối mặt với vô số xích thần trật tự do quy tắc đại đạo biến thành. Dù bị một dây xích xuyên thủng vai, Thạch Hạo vẫn phối hợp thân thể, phù văn, lôi điện, pháp môn Côn Bằng và động thiên duy nhất để phá vòng vây. Trước những lông chim, vảy và đá núi mang phù văn của các sinh linh chí cường, hắn rút Đại La kiếm thai chém mở đường. Một sinh linh đầu chim ưng sau đó cầm chiến mâu gãy mang tiên khí lao xuống tập kích, nhưng kiếm thai tự bùng phát uy năng bí ẩn và đánh kẻ đó trọng thương. Thạch Hạo chính thức bước vào khu vực sâu nhất trong khi đám đông bên ngoài tiếp tục chờ đợi kết quả. Bên trong, hắn phát hiện một chiến trường hoang vu phủ hắc vụ, chất đầy thi thể khổng lồ, binh khí gãy và máu vẫn còn nóng. Nhận thấy cuộc đại chiến dường như vừa kết thúc, hắn thận trọng giẫm qua những vũng máu và tiếp tục tiến sâu để tìm hiểu chân tướng."},{"chuong":1277,"tieuDe":"Tận Thế Chiến Trường","tomTat":"Thạch Hạo và Thiên Giác Nghĩ tiến vào một chiến trường rộng lớn phủ kín thi thể của vô số chủng tộc mạnh mẽ, nơi máu tụ thành sông hồ như cảnh tượng tận thế cuối Tiên cổ. Thạch Hạo kiểm tra máu và tinh huyết trên nhiều thi thể, phát hiện chúng vẫn phát sáng nhưng phần lớn tinh hoa, sát khí, linh tính cùng thần tính đều đã biến mất. Khi hai người tiến sâu hơn, họ nhìn thấy những cột tinh lực của các cường giả chết trận giao hòa thành trường vực cấm tuyệt, đủ sức xé rách vực ngoại và đánh rơi sao trời. Một tiếng dị khiếu từ phương xa bất ngờ cầm cố thân thể lẫn nguyên thần của cả hai, sau đó cơn lốc đen xuất hiện và nuốt lấy những luồng tinh lực khủng bố. Khi hắc phong tan đi, một chiếc ấm đen dài hơn nửa xích treo giữa trời và tiếp tục áp chế họ. Thiên Giác Nghĩ dựa theo truyền thuyết để dè dặt nhận dạng pháp khí ấy là Luyện Tiên Hồ."},{"chuong":1278,"tieuDe":"Luyện Tiên Hồ","tomTat":"Một chiếc hồ đen cổ xưa của Dị Vực xuất hiện trên chiến trường, phát ra tiếng hú quấy nhiễu tâm thần rồi hút sạch tinh hoa huyết dịch còn lại trong vô số thi thể. Thiên Giác Nghĩ giải thích đó là Luyện Tiên Hồ, hung khí từng chỉ tồn tại trong truyền thuyết từ thời Tiên Cổ, khiến nó và Thạch Hạo nghi ngờ họ đã tới Biên Hoang hoặc một cảnh tượng thuộc cuối kỷ nguyên Tiên Cổ. Sau khi thu hết tinh lực, Luyện Tiên Hồ phá không biến mất, còn hai người tiếp tục tiến về chung cực địa để tìm Bất Diệt Kinh. Trên đường, họ gặp Huyết Hoàng Sư của Dị Vực, hung thú mang huyết mạch kết hợp giữa Huyết Hoàng sa đọa và Vô Úy Sư Tử. Huyết Hoàng Sư ép hai người thần phục rồi khoe từng ăn một Thiên Giác Nghĩ có ngoại hình tương tự con kiến nhỏ, khiến Thiên Giác Nghĩ nổi giận và quyết tự tay báo thù. Trong lúc hai hung thú giao chiến dữ dội đến mức hư không nổ nát, Thạch Hạo nhìn thấy một ngọn núi tỏa kim hà, vang tiếng kinh văn và có những tờ da thú vàng lơ lửng, từ đó nghi ngờ Bất Diệt Kinh đang ở ngay phía trước."},{"chuong":1279,"tieuDe":"Huyết Hoàng Sư","tomTat":"Huyết Hoàng Sư giao chiến với Thiên Giác Nghĩ và tuyên bố từng ăn sạch một người huynh trưởng của đối phương, khiến con kiến nhỏ quyết báo thù không chết không thôi. Vì chưa trưởng thành, Thiên Giác Nghĩ ban đầu không thể áp đảo kẻ địch, nhưng sau khi bị kích động đã tiến vào cuồng bạo cảnh và làm chiến lực tăng vọt. Nó vận chuyển ba luồng tiên khí, liên tục thi triển Nghĩ quyền, đánh Huyết Hoàng Sư ho ra máu, nứt móng vuốt và suýt sụp xương trán. Huyết Hoàng Sư đáp trả bằng Sư tử Hống, khiến Thiên Giác Nghĩ chảy máu ở miệng và mắt, song vẫn không ngăn được đối phương phản kích. Quan sát trận chiến, Thạch Hạo công nhận Thiên Giác Nghĩ là đồng bạn và chiến hữu đáng dựa vào trong tương lai. Khi hắn chuyển sang chú ý trang giấy da thú màu vàng đang ngâm tụng kinh văn trên dãy núi thần thánh, một bóng người bí ẩn bất ngờ xuất hiện gần ngọn núi cổ khiến hắn chấn động."},{"chuong":1280,"tieuDe":"Số Mệnh An Bài Đại Địch","tomTat":"Thạch Hạo quan sát thanh niên thần bí đang tìm hiểu trang giấy da thú màu vàng dưới Thần sơn, không thể nhìn thấu tu vi nên âm thầm đề phòng đối phương tranh đoạt Bất Diệt Kinh. Tiểu Thiên Giác Nghĩ vì mối thù diệt gia đình mà cuồng hóa, phá vỡ không gian thôn phệ của Huyết Hoàng Sư rồi lấy đôi quyền đối đầu Huyết Hoàng trảm. Dù hai tay bị thương nặng, nó đánh gãy đôi cánh đối thủ, lột xác quyền thể và chiếm ưu thế sau hàng loạt lần va chạm trực diện. Huyết Hoàng Sư tiếp tục dùng Vô Úy Sư Tử Ấn nhưng vì khiếp sợ nên bỏ dở thế công, quay đầu chạy về phía Thần sơn và gọi thanh niên thần bí là chủ nhân. Thạch Hạo nhận ra lão Thiên Giác Nghĩ có thể đã dự liệu cuộc gặp này để giúp con trai tiêu trừ tâm ma, đồng thời cảm ứng thanh niên kia là một đại địch đáng sợ chưa từng có. Thanh niên thần bí chê Huyết Hoàng Sư mềm yếu rồi thừa nhận chính mình đã trấn áp và chém đầu huynh trưởng cùng tỷ tỷ của Tiểu Thiên Giác Nghĩ. Hắn còn cho biết từng ban một thi thể Thiên Giác Nghĩ cho Huyết Hoàng Sư ăn, khiến con kiến nhỏ đau đớn ngửa mặt gào thét."},{"chuong":1281,"tieuDe":"Thiên Hạ Vô Song","tomTat":"Tiểu Thiên Giác Nghĩ nhận ra thanh niên tóc vàng trước mặt mới là hung thủ sát hại huynh trưởng và tỷ tỷ của mình, còn Huyết Hoàng Sư chỉ là vật cưỡi của hắn. Nó khóc ra huyết lệ và định liều mạng báo thù, khiến Thạch Hạo phải ngăn lại vì biết nó chưa trưởng thành và khó có khả năng chiến thắng. Sau khi nhận thấy cưỡng ép chỉ làm chấp niệm thêm sâu, Thạch Hạo cho con kiến nhỏ xuất chiến nhưng âm thầm đưa bản thân vào trạng thái sẵn sàng cứu viện. Tiểu Thiên Giác Nghĩ thiêu đốt tiềm năng, liên tiếp thi triển Nghĩ quyền và dồn ba đạo tiên khí vào đòn mạnh nhất. Thanh niên tóc vàng vẫn né sạch hàng trăm quyền trong phạm vi vài thước rồi dùng một tay bắt cứng nắm đấm của đối phương. Hắn công bố tên Hạc Vô Song, còn Huyết Hoàng Sư lập tức ca tụng huyết mạch chủ nhân và sỉ nhục toàn bộ tuấn kiệt trẻ tuổi của thế giới đối địch."},{"chuong":1282,"tieuDe":"Dị Vực Lĩnh Quân Nhân","tomTat":"Tiểu Thiên Giác Nghĩ dốc toàn lực phản kháng nhưng vẫn bị Hạc Vô Song dùng sức mạnh thân thể áp chế và làm bị thương. Thạch Hạo tiến lên bảo vệ con kiến, trong khi Huyết Hoàng Sư công bố chủ nhân mình là một trong những lĩnh quân nhân trẻ tuổi của thế giới bên kia. Qua lời nói của Thạch Hạo, Hạc Vô Song nhận ra đối phương cùng Tiểu Thiên Giác Nghĩ không thuộc thời đại hiện tại, nhưng hắn không kinh hoảng vì sư tôn từng gặp trường hợp tương tự. Hắn bác đề nghị giết con kiến và muốn giữ lại cá thể có thể là huyết thống cuối cùng của bộ tộc Thiên Giác Nghĩ. Thạch Hạo mở màn giao phong bằng Luân Hồi bảo thuật, còn Hạc Vô Song dùng Tụ lý càn khôn cùng Thế Giới Trong Lòng Bàn Tay để đối kháng, khiến hai bên tạm thời chưa phân thắng bại. Sau cuộc va chạm, Hạc Vô Song xác định Thạch Hạo cũng nhắm tới Bất Diệt Kinh trên các trang da thú màu vàng và tuyên bố mình vẫn chưa sử dụng phương pháp của Dị vực."},{"chuong":1283,"tieuDe":"Tuyệt Đỉnh Cuộc Chiến","tomTat":"Trong dãy núi được ánh sáng từ những trang da thú nhuộm vàng, tràng vực tinh khí thần của Thạch Hạo và Hạc Vô Song va chạm dữ dội, khiến núi đá vỡ nát và không gian sụp đổ trước khi hai người chính thức giao thủ. Tiểu Thiên Giác Nghĩ vì thù hận mà cuồng hóa, hai lần lao vào Hạc Vô Song nhưng đều bị đánh văng, còn đối phương tuyên bố muốn bắt nó làm chiến nô. Thạch Hạo chủ động phát động cuộc chiến, kết hợp thân thể, chớp giật, Côn Bằng vũ và nhiều bảo thuật để đối đầu với hỗn độn cùng kiếm quyết của Hạc Vô Song. Khi Hạc Vô Song thi triển ba thức kiếm quyết không hoàn chỉnh có sức công phạt sánh với Bình Loạn Quyết, Thạch Hạo vận chuyển Nguyên Thủy Chân Giải và diễn hóa hình thái sinh linh trong Vạn Linh Đồ trên hai tay để chống đỡ. Hiệp cận chiến đầu tiên kết thúc mà không ai đổ máu, cho thấy thân thể và thần thông của hai người đang cân sức. Hạc Vô Song xác nhận cả hai cùng nhắm đến Bất Diệt Kinh và coi cuộc tranh đoạt là cuộc đối đầu đạo vận giữa hai thế giới. Thạch Hạo chấp nhận dùng sinh tử quyết định người sở hữu kinh văn, yêu cầu Tiểu Thiên Giác Nghĩ giết Huyết Hoàng Sư rồi chuẩn bị dốc toàn lực đánh giết Hạc Vô Song."},{"chuong":1284,"tieuDe":"Thiên Khóc","tomTat":"Thạch Hạo và Hạc Vô Song dốc toàn bộ tiềm năng vào cuộc quyết chiến mang vận mệnh của hai giới, khiến tiên khí, khói xám và đạo vận dị vực va chạm dữ dội. Giữa trận chiến, mưa máu thiên khóc trút xuống và những khuôn mặt đẫm huyết lệ của tiên dân kỷ nguyên trước hiện lên, truyền nỗi đau mất sơn hà cùng ý chí bất khuất tới Thạch Hạo. Đạo vận hai giới lần lượt hóa hình quanh hai đối thủ, còn Thạch Hạo thi triển Lục Đạo Luân Hồi Thiên Công để đối đầu bốn kiếm thai Tru Tiên của Hạc Vô Song. Khi Đại La kiếm thai khiến đối thủ tránh giao phong trực diện, Thạch Hạo dùng dấu ấn Nguyên Thần giả dạng Bình Loạn Quyết để ép Hạc Vô Song lui lại và giành thời cơ áp sát. Hắn tiếp tục nén duy nhất động thiên có khắc phù văn Nguyên Thủy Chân Giải rồi cho bùng nổ, trong khi Hạc Vô Song phối hợp Vạn pháp thành không với Thí Tiên Thuật. Hai người đều sống sót và bị đánh văng đến chảy máu, chưa bên nào giành được thắng lợi. Dưới trận mưa máu, cả hai lại gom sát ý và toàn bộ bảo thuật để chuẩn bị đòn cuối quyết định sinh tử."},{"chuong":1285,"tieuDe":"Quang Và Ám","tomTat":"Thạch Hạo chồng chất nhiều bảo thuật vào đòn mạnh nhất, mang theo ý chí quyết tử để đối đầu Hạc Vô Song. Một bên bùng sáng như liệt dương, bên kia hóa thành vực sâu hắc ám, khiến chiến trường tan vỡ và Hỗn Độn khí trào ra khi hai sức mạnh va chạm. Sau khi thần quang suy yếu, Tiểu Thiên Giác Nghĩ phát hiện tàn chi cùng nửa thân thể không đầu của Thạch Hạo, nhưng chưa thể xác nhận hắn đã chết. Huyết Hoàng Sư ban đầu chế nhạo đối phương, song nhanh chóng hoảng loạn khi thấy máu xám bạc và thân thể tan rã của Hạc Vô Song. Hai tùy tùng cùng lao vào các khe nứt hư không tìm kiếm chủ nhân, đồng thời đề phòng đối phương đánh lén hoặc phá hoại. Một sức mạnh thần bí giữ các khe nứt không khép lại, để lộ Hỗn Độn cung điện đang mở rộng cửa ở nơi sâu nhất. Bên trong cung điện có những vật đáng sợ đang đối đầu, báo hiệu một cuộc va chạm tuyệt thế khác sắp xảy ra."},{"chuong":1286,"tieuDe":"Sống Sót","tomTat":"Trong Hỗn Độn Cung Điện, Đại la kiếm thai bộc phát kiếm quang đối đầu Luyện Tiên Hồ, khiến chính cổ điện phát lực áp súc không gian và trấn áp cả hai binh khí. Thiên Giác Nghĩ cùng Huyết Hoàng Sư tìm kiếm những người sống sót giữa các khe nứt hư không đầy máu, xương vỡ và mảnh pháp khí. Không tìm thấy Thạch Hạo, Thiên Giác Nghĩ tưởng người bạn đầu tiên của mình đã chết nên thề tương lai sẽ đánh sang Dị vực báo thù. Hạc Vô Song được phát hiện vẫn còn sống dù đầu lâu bị xuyên thủng, sau đó nối lại thân thể và dùng bảo đan chữa thương. Thạch Hạo bất ngờ xuất hiện phía sau đối thủ, hợp nhất đầu lâu với thân thể rồi uống giọt Trường Sinh dịch cuối cùng để nhanh chóng tái sinh. Hạc Vô Song lập tức dùng dược tra Cửu Chuyển Tiên Đan, sau đó lao lên ngọn núi đặt Bất Diệt Kinh thay vì tiếp tục quyết chiến tại khe nứt. Thạch Hạo truy kích, cùng hắn vượt qua cấm chế và vừa tranh trang da thú màu vàng vừa giao chiến trên đỉnh núi."},{"chuong":1287,"tieuDe":"Đồng Quy Vu Tận","tomTat":"Thạch Hạo và Hạc Vô Song vừa tranh đoạt những trang Bất Diệt Kinh vừa quyết chiến, rồi cùng bỏ việc giằng co kinh văn để tập trung giết đối thủ. Thạch Hạo vận chuyển Pháp môn Côn Bằng, Kim Tuyền Ba Văn Công và Nguyên Thủy Chân Giải, đồng thời triển khai ba chùm sáng ứng với quá khứ, hiện tại và tương lai, dù pháp này vẫn chưa hoàn chỉnh. Sau tám trăm hiệp bất phân thắng bại, Hạc Vô Song cầm cố thời không, buộc Thạch Hạo tự ngộ cách lấy thân hóa thành đao thai, áp duy nhất động thiên sát da và khắc phù văn để phá vây. Hạc Vô Song tiếp tục thi triển Quân lâm thiên hạ, triệu hoán đạo tắc Dị vực nhằm áp chế quy tắc tàn khuyết của thế giới này, nhưng Thạch Hạo không bị ảnh hưởng nhờ con đường lấy thân làm loại. Trong đòn quyết định, Thạch Hạo đánh xuyên xương trán Hạc Vô Song, còn Hạc Vô Song dùng chỉ kiếm xé mi tâm và đánh nát nguyên thần đối thủ, khiến Thiên Giác Nghĩ cùng Huyết Hoàng Sư tin rằng cả hai đã đồng quy vu tận. Mạch kể sau đó chuyển qua quãng thời gian dài như một kỷ nguyên, khi chiến trường mất thần tính, thi thể và Bất Diệt Kinh đều biến mất; cuối cùng một con kiến nhỏ đào lên chiếc sọ có lỗ thủng đáng sợ tại mi tâm."},{"chuong":1288,"tieuDe":"Đạo Thứ Năm","tomTat":"Thạch Hạo và Tiểu Thiên Giác Nghĩ tỉnh lại giữa cổ chiến trường sau trải nghiệm chân thực như luân hồi, trong đó Thạch Hạo đã đồng quy vu tận với Hạc Vô Song. Dù thân thể không có thương tích hữu hình, Thạch Hạo vẫn kiệt sức và phát hiện Trường Sinh dịch đã biến mất, đồng thời trên tay xuất hiện Luân Hồi ấn thứ năm. Hai người vội lên Thần sơn tìm những trang da thú chứa Bất Diệt Kinh nhưng chỉ thấy núi non u ám, vết máu đỏ sậm và một con kiến thường chưa khai hóa. Khi họ định lay chuyển ngọn núi, ô quang đánh bật cả hai và hóa thành Quạ đen anh linh cùng vô số chiến hồn của cường giả chết trận. Quạ đen xác nhận cổ chiến trường trước mắt mới là chung cực nơi tập luyện thật sự, còn cảnh biển máu và thi thể là diện mạo nơi này sau khi bị Dị vực chiếm giữ. Nó cũng cho biết Hạc Vô Song là nhân vật có thật, từng lĩnh quân thế hệ trẻ Dị vực vào cuối thời Tiên cổ. Trận quyết chiến vừa qua là một thử thách chân thực, dùng để xác định Thạch Hạo có đủ tư cách và duyên phận tiếp cận Bất Diệt Kinh hay không."},{"chuong":1289,"tieuDe":"Bất Diệt","tomTat":"Lão quạ đen giải thích rằng cuộc giao chiến của Thạch Hạo vừa tái hiện trận tử chiến giữa Hạc Vô Song và một hạt giống mạnh mẽ cuối thời Tiên cổ, vừa có khả năng là cuộc gặp chân thân xuyên qua thời gian. Hạt giống Tiên cổ ấy từng được che giấu để bảo toàn hy vọng, nhưng sau khi cảm nhận thân nhân chết trận đã trở lại chiến trường và cuối cùng bị Hạc Vô Song giết. Quạ đen xác nhận Hạc Vô Song vẫn sống sau một kỷ nguyên, khiến Tiểu Thiên Giác Nghĩ thề báo thù, còn Thạch Hạo nhìn Luân Hồi ấn thứ năm và quyết tâm mau chóng mạnh lên. Khi Thạch Hạo hỏi Bất Diệt Kinh, quạ đen cho biết Hạc Vô Song chỉ lấy được bốn trong tổng số chín trang nên chưa thể luyện đến đại thành, còn năm trang cuối được truyền là nằm trong một vùng cấm đáng sợ. Bất Diệt Kinh vốn khắc trên Bất Diệt phong; dù nhiều Bất Hủ Dị vực từng dùng Luyện Tiên Hồ cùng đại pháp lực đánh gãy ngọn núi, truyền thừa vẫn tự khôi phục và tái hiện. Thạch Hạo lấy chiếc chìa khóa bằng bạch cốt từng tìm được tại tiên gia cổ chiến trường ra và được xác nhận đó chính là Kinh thược cần thiết để tiếp cận kinh văn. Cuối chương, hắn nhớ tới Tiểu Hoàng Điệp và Đả Thần Thạch vẫn đang ngủ say để hoàn thành quá trình lột xác và tiến hóa."},{"chuong":1290,"tieuDe":"Kinh Thư Tới Tay","tomTat":"Thạch Hạo và Thiên Giác Nghĩ nhỏ tìm được cách lấy Bất Diệt Kinh, nhưng Thạch Hạo vẫn thận trọng kiểm chứng lời chỉ dẫn của quạ đen. Hắn truyền pháp lực vào chìa khóa bạch cốt, khiến vật này nhập vào Bất Diệt Phong và làm ngọn núi rạn nứt, tan rã, để lộ bốn trang kinh thư màu vàng. Vì những trang kinh quá nặng, hai người không thể mang đi mà chuyển sang ghi nhớ toàn bộ văn tự thể hiện đạo lý vượt khỏi giới hạn kỷ nguyên. Sau khi kinh văn được khắc sâu vào tâm trí họ, bốn trang cùng dị tượng nhật nguyệt tinh tú biến mất. Quạ đen cho biết đây là bản thượng hoàn chỉnh, đủ tu hành tới Chí Tôn, còn bản hạ gồm năm trang được cất tại bất tử nơi. Trước sự nôn nóng của Thiên Giác Nghĩ nhỏ, Thạch Hạo khuyên nó trước hết tu luyện phần đã có và xây chắc căn cơ."},{"chuong":1291,"tieuDe":"Bại Hoại","tomTat":"Thạch Hạo và Thiên Giác Nghĩ lấy được phần thượng Bất Diệt Kinh, còn năm trang phần hạ vẫn nằm tại Bất Tử nơi. Trước khi họ rời đi, quạ đen cảnh báo về sát khí dưới cổ địa, sắp xếp lại đá núi rồi tan thành những gương mặt tuyệt vọng, bộc lộ bản chất là chấp niệm của các anh linh Tiên cổ. Chứng kiến thảm cảnh quân dân Tiên cổ bị dị vực tàn sát, Thạch Hạo thề không để lịch sử ấy tái diễn, còn Thiên Giác Nghĩ quyết trở nên mạnh hơn để báo thù cho người thân. Việc Thạch Hạo sống sót rời chung cực nơi tập luyện phá vỡ thần thoại tử địa và gây chấn động khắp Bắc Hải. Tuy nhiên, ngay khi rời vùng nguy hiểm, hắn bị cuồng phong đưa ra vực ngoại, nơi Vương Mãng Long cùng một lão giả Vương gia đã bố trí sát cục. Vương Mãng Long tiết lộ lần khiêu khích ở Thiên Thần thư viện vốn nhằm tạo cớ tư thù, còn cả hai kẻ phục kích đều chấp nhận hy sinh để giết Thạch Hạo và đoạt tạo hóa cho gia tộc. Lão giả tuyên bố chỉ cần Vương gia tồn tại thì thiên hạ hay chúng sinh bị dị vực hủy diệt cũng không liên quan tới mình, khiến Thạch Hạo phẫn nộ mắng người Vương gia là bại hoại."},{"chuong":1292,"tieuDe":"Dẫn Xà Xuất Động","tomTat":"Tại Bắc Hải, Thạch Hạo phẫn nộ khi Huyền Tổ của Vương Mãng Long thừa nhận Vương gia từng bàn điều kiện với dị vực, dù lão phủ nhận hai bên đã trực tiếp liên thủ. Vương Mãng Long thúc giục Huyền Tổ bắt sống Thạch Hạo, còn lão vừa muốn cướp cơ duyên và diệt khẩu vừa nhắm tới việc nuôi nhốt Thiên Giác Nghĩ để lấy bảo huyết cho hậu duệ. Trong lúc nói chuyện kéo dài thời gian, Huyền Tổ âm thầm giam cầm hư không để ngăn Thạch Hạo trốn thoát hoặc phá hủy kinh văn. Thạch Hạo bất ngờ tuyên bố thứ mình lấy được là Bất Diệt Kinh, khiến phía Vương gia lập tức động lòng tham và dụ được ba cao thủ ẩn nấp hiện thân. Người mặc giáp bạc phá cấm chế, còn bóng người phủ khói đen và sinh linh trong ánh sáng xanh lục cũng xuất hiện, tất cả đều chỉ nhắm tới kinh văn. Huyền Tổ đề nghị sao chép Bất Diệt Kinh thành bốn phần rồi để Vương gia giết Thạch Hạo. Tuy nhiên, Thạch Hạo vẫn bình tĩnh gọi đích danh Nguyên Thanh, khiến toàn bộ những kẻ vây quanh nhận ra tình hình bất thường và bắt đầu nghi ngờ mình đã mắc bẫy."},{"chuong":1293,"tieuDe":"Không Thể Vượt Qua Một Cái Tuyến","tomTat":"Thạch Hạo bị Vương Mãng Long, một ông lão Vương gia và ba cường giả thuộc các gia tộc cổ vây giữa vực ngoại, nhưng vẫn bình tĩnh dùng nghi binh khiến họ dè chừng. Sau khi ông lão dùng thần thông dò xét và xác nhận không có cao thủ mai phục, lão ra tay định bắt giữ hắn. Thạch Hạo lập tức bóp nát Dưỡng Tiên ngọc, giải phóng linh thân Mạnh Thiên Chính đang được che giấu bên trong. Mạnh Thiên Chính đánh nát bàn tay ông lão, bắt giữ lão, phong tỏa ba cường giả bỏ chạy rồi phá hủy giáp trụ và mặt nạ của họ. Ông dùng Ngân hà hóa thần kiếm tiêu diệt cả ba, sau đó phá hủy thân thể và thiêu sạch Nguyên Thần ông lão Vương gia. Thạch Hạo tự tay đánh chết Vương Mãng Long bằng một quyền. Cuối cùng, Mạnh Thiên Chính thu hai cỗ tàn thi người Vương gia, mang Thạch Hạo xé trời tiến thẳng tới Trường Sinh thế gia này để hỏi tội và cảnh cáo những kẻ dám vượt qua giới hạn."},{"chuong":1294,"tieuDe":"Đại Trưởng Lão Uy Thế","tomTat":"Đại Trưởng Lão mang Thạch Hạo xé rách tinh vực, vượt qua khoảng cách vốn cần hàng trăm hoặc hàng nghìn Truyền Tống trận để đến địa bàn Vương gia tại Vô Lượng Thiên. Trước Trường Sinh vương phủ, Tử kim Bạo Viên viện dẫn quy củ của gia tộc để chặn đường nhưng bị ông phất tay áo đánh trọng thương và hất bay hàng nghìn dặm. Nhận ra vùng núi sông tám trăm dặm phía trước đã bị bố trí tuyệt sát đại trận, Đại Trưởng Lão tính toán trận thế rồi cưỡng ép đưa Thạch Hạo vượt qua giữa lôi đình, đất nứt và dung nham. Kim Sí Đại Bàng bán bộ Chí Tôn tiếp tục lao xuống tấn công, song bị ông thu nhỏ đến cỡ bàn tay, giam giữ rồi đánh ngất. Khi một người của Vương gia lên tiếng chất vấn, Đại Trưởng Lão ném nửa thân thể Vương Mãng Long cùng đầu một ông lão trong tộc vào cổng chào. Cổng chào đổ sập trong bụi đất, khiến cuộc đối đầu trực tiếp với Trường Sinh gia tộc chính thức bị đẩy tới trước cửa."},{"chuong":1295,"tieuDe":"Cường Giả Tuyệt Thế","tomTat":"Mạnh Thiên Chính dẫn Thạch Hạo vượt qua sơn môn đổ nát và tiến sâu vào tịnh thổ Vương gia. Một người trung niên trấn cổng dùng Phá Thiên Thức tấn công nhưng bị ông hóa giải, bắt giữ và đánh trọng thương. Khi di thể của Vương Mãng Long cùng lão giả Vương gia được đưa vào Ngôi sao điện, cửu thế tổ xuất hiện, tuyên bố không cần xét đúng sai và dùng chí tôn đao khí hạ sát Thạch Hạo. Mạnh Thiên Chính phá tan đao khí, đánh gãy xương sống cửu thế tổ rồi chém nát thân thể, trọng thương nguyên thần của đối phương. Ông tiếp tục dùng cái đầu còn lại phá hủy Ngôi sao điện, khiến toàn bộ Vương gia chấn động. Sau đó, Mạnh Thiên Chính gọi đích danh Vương Trường Sinh ra gặp, lập tức dẫn tới sự xuất hiện của ít nhất ba cường giả tuyệt thế tắm trong tiên huy. Uy thế của họ khiến Thiên Giác Nghĩ nhận ra tình thế đã trở nên đặc biệt nguy hiểm."},{"chuong":1296,"tieuDe":"Chín Con Rồng","tomTat":"Bốn cao thủ tuyệt đỉnh của Vương gia xuất hiện chặn đường, khiến Thạch Hạo biết tên thật của Đại trưởng lão là Mạnh Thiên Chính và nhận ra họ là bốn trong chín người con của Vương Trường Sinh. Vương Đại tuyên bố Vương gia nhất định giết hoặc trấn áp Thạch Hạo, sau đó dùng thần thông luyện hóa đại tinh để giao chiến với Mạnh Thiên Chính nhưng bị đối phương tát vào mặt. Vương Nhị lấy sức mạnh của chín huynh đệ uy hiếp, còn Mạnh Thiên Chính công khai thách cả chín con rồng cùng xuất hiện. Năm luồng huyết khí lập tức dâng lên từ sâu trong Vương gia, song Vương Trường Sinh lên tiếng quát dừng các con. Ông dùng ngân bạch huyết khí hóa thành Đại Đạo Chi Hoa, thu lấy tinh hoa sao trời ngoài Ngoại Vực và khiến Mạnh Thiên Chính lần đầu cảm thấy áp lực. Vương Trường Sinh ra lệnh mời khách vào trong, còn bốn người con buộc phải lui lại. Bất chấp sự lo ngại của Kim và nguy cơ phải đối diện toàn bộ nội tình Vương gia, Mạnh Thiên Chính vẫn dẫn Thạch Hạo tiến sâu vào gia tộc để đòi lời giải thích và tiêu trừ hậu họa cho hắn."},{"chuong":1297,"tieuDe":"Vương Gia Gốc Gác","tomTat":"Vương Trường Sinh được hé lộ là nhân vật cấm kỵ sống từ cổ đại, quanh lai lịch có truyền thuyết rằng hắn là Tiên thai từng được Chân Tiên của Vương gia phong ấn, truyền thụ và quán đỉnh. Sau khi hắn ngăn các con tiếp tục giao chiến, Mạnh Thiên Chính dẫn Thạch Hạo tiến sâu vào cổ địa Vương gia, nơi hơn vạn linh sơn và kiến trúc Tiên cổ hợp thành một đại trận khổng lồ. Trên đường, họ chứng kiến Hắc Hống thuần huyết, vượn già màu trắng, đàn Kim Ô và lão Kim Ô đều là những hung vật được Vương gia nuôi dưỡng hoặc hàng phục để bảo vệ cổ địa. Trước tổ điện do thủy tổ Chân Tiên xây dựng, chín người con của Vương Trường Sinh cùng tụ hội, trong đó Vương Lục và Vương Thất lần lượt tỏ ý khiêu chiến Mạnh Thiên Chính còn Vương Cửu bộc lộ khí tượng đặc biệt thâm sâu. Vương Trường Sinh nhìn thấu người đang hiện diện chỉ là linh thân, khiến chân thân Mạnh Thiên Chính vượt không tới và dung hợp với linh thân ngay tại hiểm địa. Cuối cùng, Vương Trường Sinh bước ra khỏi tổ điện dưới hình dáng một thiếu niên, khiến Thạch Hạo hoàn toàn sửng sốt."},{"chuong":1298,"tieuDe":"Vương Trường Sinh","tomTat":"Thạch Hạo dùng Thiên Nhãn thông xác nhận Vương Trường Sinh thực sự có thân thể và sinh cơ của một thiếu niên khoảng mười tám tuổi, chứ không chỉ biến hóa vẻ ngoài. Vương Trường Sinh thừa nhận lần lột xác đời thứ hai chưa hoàn chỉnh vì thần thai còn tỳ vết, rồi cùng Mạnh Thiên Chính bàn về sự biến mất của vật chất bất tử và thời đại mạt pháp sắp tới. Khi bị chất vấn về lý do xông vào Vương gia, Mạnh Thiên Chính công khai coi Thạch Hạo là đệ tử quan môn có địa vị như hậu nhân và tuyên bố mình đến để đòi lời giải thích, giết người. Vương Bát chủ động xin giao chiến, còn Vương Trường Sinh sau đó đề nghị để cả chín người con cùng vây đánh đối phương. Trước thế bao vây, Mạnh Thiên Chính mở Thập Giới Đồ, lập tức đánh văng những người áp sát và khiến một người ho ra máu. Uy lực của chí bảo buộc Vương Trường Sinh phải dè chừng vì đại chiến có thể phá hủy tịnh thổ, giết nhiều hậu nhân Vương gia và khiến vài người trong chín con trai của ông tử trận."},{"chuong":1299,"tieuDe":"Đối Lập","tomTat":"Vương Trường Sinh gọi tổ truyền chiến kích từ mi tâm để đối chọi Thập Giới Đồ của Mạnh Thiên Chính, phóng chùm sáng xuyên trời và phá hủy nhiều đại tinh ngoài vực. Mạnh Thiên Chính thúc động Thập Giới Đồ làm hư không quanh tổ điện sụp đổ, đồng thời tuyên bố mình đến Vương gia để đòi công bằng cho Thạch Hạo. Vương Trường Sinh khởi động tiên trận lấy một vạn ngọn núi làm nền và quyết định cùng chín người con, tổ binh cùng trận pháp hợp lực vây bắt đối thủ, thay vì để Vương Cửu đơn đấu. Khi thế công của đại trận bao phủ trời đất, Mạnh Thiên Chính gọi ra một mảnh vải rách nhuốm máu và hóa giải toàn bộ ánh sáng đang lao tới. Vương Trường Sinh cùng Vương Đại nhận ra đó là Tiên Vương quấn vải liệm, trận kỳ gắn với vận mệnh của Trường Sinh hoàng triều Từ gia. Việc Từ gia cho Mạnh Thiên Chính mượn bảo vật này khiến Vương Trường Sinh bất ngờ, còn Thạch Hạo nhận biết mảnh vải mang lai lịch lớn và một quá khứ đầy huyết lệ."},{"chuong":1300,"tieuDe":"Tiên Cổ Chiến Kỳ","tomTat":"Tiên Cổ Chiến Kỳ của Từ gia được hé lộ là hiệu kỳ từng theo Chân Tiên nghênh chiến dị vực, sau đó bọc di thể tan nát của hai Tiên vương và hấp thu tinh huyết bản nguyên của họ. Một cao thủ Vương gia gọi nó là lá cờ rách liền bị tiếng hừ của Mạnh Thiên Chính đánh nổ thành mưa máu. Vương Trường Sinh nhận ra chiến kỳ có thể mở đường qua trận pháp Tiên đạo, còn khi phối hợp với Thập Giới Đồ và sức mạnh của Mạnh Thiên Chính thì đủ gây tổn thất khổng lồ cho cổ địa Vương gia. Mạnh Thiên Chính buộc Vương Trường Sinh quản thúc con cháu và cảnh cáo sẽ giết chín người con của ông nếu Vương gia tiếp tục làm hại Thạch Hạo. Được hỏi muốn bồi thường gì, Thạch Hạo xin xem Bình Loạn Quyết nhưng bị Vương Trường Sinh từ chối. Hai đại cường giả cuối cùng chọn giao đấu ba hoặc bốn chiêu bằng tay không, dung hợp vạn đạo và sát thức Thập Hung vào những động tác giản dị. Đến thức thứ ba, dư uy vô hình đã làm một linh sơn có tiên gia phù văn nứt vỡ rồi nổ tung."}];
